    12→void UWjWorldCosmeticSubsystem::Initialize(FSubsystemCollectionBase& Collection)
    13→{
    14→	Super::Initialize(Collection);
    15→
    16→	// DeveloperSettings에서 카탈로그 로드
    17→	const UWjWorldDeveloperSettings* Settings = GetDefault<UWjWorldDeveloperSettings>();
    18→	if (Settings && !Settings->CosmeticCatalog.IsNull())
    19→	{
    20→		Catalog = Settings->CosmeticCatalog.LoadSynchronous();
    21→		UE_LOG(LogWjWorldCosmetic, Log, TEXT("카탈로그 로드: %s"), Catalog ? *Catalog->GetName() : TEXT("실패"));
    22→	}
    23→	else
    24→	{
    25→		UE_LOG(LogWjWorldCosmetic, Warning, TEXT("DeveloperSettings에 CosmeticCatalog가 설정되지 않았습니다."));
    26→	}
    27→
    28→	LoadLoadoutFromLocal();
    29→
    30→	// Steam 인벤토리 초기 로드
    31→	RequestInventoryRefresh();
    32→
    33→	UE_LOG(LogWjWorldCosmetic, Log, TEXT("CosmeticSubsystem 초기화 완료"));
    34→}
    35→
    36→void UWjWorldCosmeticSubsystem::Deinitialize()
    37→{
    38→	StopInventoryPolling();
    39→	SaveLoadoutToLocal();
    40→
    41→#if WITH_STEAM
    42→	// 대기 중인 결과 핸들 정리
    43→	if (PendingResultHandle != k_SteamInventoryResultInvalid)
    44→	{
    45→		ISteamInventory* SteamInv = SteamInventory();
    46→		if (SteamInv)
    47→		{
    48→			SteamInv->DestroyResult(PendingResultHandle);
    49→		}
    50→		PendingResultHandle = k_SteamInventoryResultInvalid;
    51→	}
    52→#endif
    53→
    54→	Super::Deinitialize();
    55→}
