   181→void UWjWorldCosmeticSubsystem::SaveLoadoutToLocal()
   182→{
   183→	for (const FCosmeticSlotEntry& Entry : CurrentLoadout.Entries)
   184→	{
   185→		FString SlotKey = FString::Printf(TEXT("Slot_%d"), static_cast<int32>(Entry.Slot));
   186→		GConfig->SetString(*LoadoutConfigSection, *SlotKey, *Entry.ItemId.ToString(), GGameUserSettingsIni);
   187→	}
   188→
   189→	GConfig->Flush(false, GGameUserSettingsIni);
   190→	UE_LOG(LogWjWorldCosmetic, Log, TEXT("로드아웃 로컬 저장 완료"));
   191→}
   192→
   193→void UWjWorldCosmeticSubsystem::LoadLoadoutFromLocal()
   194→{
   195→	CurrentLoadout.Reset();
   196→
   197→	for (int32 SlotIdx = static_cast<int32>(ECosmeticSlot::Head);
   198→		SlotIdx <= static_cast<int32>(ECosmeticSlot::Effect); ++SlotIdx)
   199→	{
   200→		FString SlotKey = FString::Printf(TEXT("Slot_%d"), SlotIdx);
   201→		FString ItemIdStr;
   202→		if (GConfig->GetString(*LoadoutConfigSection, *SlotKey, ItemIdStr, GGameUserSettingsIni))
   203→		{
   204→			if (!ItemIdStr.IsEmpty())
   205→			{
   206→				CurrentLoadout.Equip(static_cast<ECosmeticSlot>(SlotIdx), FName(*ItemIdStr));
   207→			}
   208→		}
   209→	}
   210→
   211→	UE_LOG(LogWjWorldCosmetic, Log, TEXT("로드아웃 로컬 로드 완료 (%d 슬롯)"), CurrentLoadout.Entries.Num());
   212→}
