   246→void UWjWorldCosmeticSubsystem::PollSteamInventoryResult()
   247→{
   248→#if WITH_STEAM
   249→	if (PendingResultHandle == k_SteamInventoryResultInvalid)
   250→	{
   251→		StopInventoryPolling();
   252→		return;
   253→	}
   254→
   255→	ISteamInventory* SteamInv = SteamInventory();
   256→	if (!SteamInv)
   257→	{
   258→		StopInventoryPolling();
   259→		return;
   260→	}
   261→
   262→	EResult Status = SteamInv->GetResultStatus(PendingResultHandle);
   263→
   264→	if (Status == k_EResultPending)
   265→	{
   266→		// 아직 대기 중 - 계속 폴링
   267→		return;
   268→	}
   269→
   270→	// 결과 처리
   271→	if (Status == k_EResultOK)
   272→	{
   273→		UE_LOG(LogWjWorldCosmetic, Log, TEXT("Steam 인벤토리 결과 수신 성공"));
   274→		ParseInventoryResult();
   275→	}
   276→	else
   277→	{
   278→		UE_LOG(LogWjWorldCosmetic, Warning, TEXT("Steam 인벤토리 결과 실패 (Status: %d)"), static_cast<int32>(Status));
   279→	}
   280→
   281→	// 정리
   282→	SteamInv->DestroyResult(PendingResultHandle);
   283→	PendingResultHandle = k_SteamInventoryResultInvalid;
   284→	StopInventoryPolling();
   285→
   286→	// 델리게이트 브로드캐스트
   287→	OnInventoryUpdated.Broadcast();
   288→#else
   289→	StopInventoryPolling();
   290→#endif
   291→}
   292→
   293→void UWjWorldCosmeticSubsystem::ParseInventoryResult()
   294→{
   295→#if WITH_STEAM
   296→	ISteamInventory* SteamInv = SteamInventory();
   297→	if (!SteamInv || !Catalog)
   298→	{
   299→		UE_LOG(LogWjWorldCosmetic, Warning, TEXT("ParseInventoryResult: SteamInventory 또는 Catalog 없음"));
   300→		return;
   301→	}
   302→
   303→	if (PendingResultHandle == k_SteamInventoryResultInvalid)
   304→	{
   305→		return;
   306→	}
   307→
   308→	// 아이템 개수 확인
   309→	uint32 ItemCount = 0;
   310→	if (!SteamInv->GetResultItems(PendingResultHandle, nullptr, &ItemCount) || ItemCount == 0)
   311→	{
   312→		UE_LOG(LogWjWorldCosmetic, Log, TEXT("Steam 인벤토리: 아이템 0개"));
   313→		CachedInventory.Empty();
   314→		return;
   315→	}
   316→
   317→	// 아이템 상세 정보 가져오기
   318→	TArray<SteamItemDetails_t> ItemDetails;
   319→	ItemDetails.SetNum(ItemCount);
   320→
   321→	if (!SteamInv->GetResultItems(PendingResultHandle, ItemDetails.GetData(), &ItemCount))
   322→	{
   323→		UE_LOG(LogWjWorldCosmetic, Warning, TEXT("Steam 인벤토리 아이템 상세 정보 가져오기 실패"));
   324→		return;
   325→	}
   326→
   327→	// 캐시된 인벤토리 갱신
   328→	CachedInventory.Empty(ItemCount);
   329→
   330→	for (uint32 i = 0; i < ItemCount; ++i)
   331→	{
   332→		const SteamItemDetails_t& Details = ItemDetails[i];
   333→
   334→		// SteamItemDefId → ItemId 변환
   335→		FName ItemId = Catalog->SteamItemDefIdToItemId(Details.m_iDefinition);
   336→		if (ItemId.IsNone())
   337→		{
   338→			UE_LOG(LogWjWorldCosmetic, Warning, TEXT("알 수 없는 SteamItemDefId: %d"), Details.m_iDefinition);
   339→			continue;
   340→		}
   341→
   342→		// 수량 체크 (0이면 소비됨/만료됨)
   343→		if (Details.m_unQuantity == 0)
   344→		{
   345→			continue;
   346→		}
   347→
   348→		// 기존 아이템 수량 증가 또는 새로 추가
   349→		FCosmeticItemInstance* Existing = CachedInventory.FindByPredicate([ItemId](const FCosmeticItemInstance& Inst)
   350→		{
   351→			return Inst.ItemId == ItemId;
   352→		});
   353→
   354→		if (Existing)
   355→		{
   356→			Existing->Quantity += Details.m_unQuantity;
   357→		}
   358→		else
   359→		{
   360→			FCosmeticItemInstance NewItem(ItemId);
   361→			NewItem.Quantity = Details.m_unQuantity;
   362→			CachedInventory.Add(NewItem);
   363→		}
   364→
   365→		UE_LOG(LogWjWorldCosmetic, Verbose, TEXT("인벤토리 아이템: %s (DefId: %d, Qty: %d)"),
   366→			*ItemId.ToString(), Details.m_iDefinition, Details.m_unQuantity);
   367→	}
   368→
   369→	UE_LOG(LogWjWorldCosmetic, Log, TEXT("Steam 인벤토리 파싱 완료: %d개 아이템"), CachedInventory.Num());
   370→#endif
   371→}
