   373→bool UWjWorldCosmeticSubsystem::AddPromoItem(int32 SteamItemDefId)
   374→{
   375→#if WITH_STEAM
   376→	ISteamInventory* SteamInv = SteamInventory();
   377→	if (!SteamInv)
   378→	{
   379→		UE_LOG(LogWjWorldCosmetic, Warning, TEXT("AddPromoItem: Steam Inventory API 사용 불가"));
   380→		return false;
   381→	}
   382→
   383→	SteamItemDef_t ItemDef = static_cast<SteamItemDef_t>(SteamItemDefId);
   384→	SteamInventoryResult_t ResultHandle = k_SteamInventoryResultInvalid;
   385→
   386→	if (SteamInv->AddPromoItem(&ResultHandle, ItemDef))
   387→	{
   388→		UE_LOG(LogWjWorldCosmetic, Log, TEXT("AddPromoItem: 프로모 아이템 지급 요청 성공 (DefId: %d)"), SteamItemDefId);
   389→
   390→		// 결과 핸들 정리 (비동기 결과는 나중에 인벤토리 갱신으로 확인)
   391→		SteamInv->DestroyResult(ResultHandle);
   392→
   393→		// 인벤토리 갱신 요청
   394→		RequestInventoryRefresh();
   395→		return true;
   396→	}
   397→	else
   398→	{
   399→		UE_LOG(LogWjWorldCosmetic, Warning, TEXT("AddPromoItem: Steam AddPromoItem 실패 (DefId: %d)"), SteamItemDefId);
   400→		return false;
   401→	}
   402→#else
   403→	UE_LOG(LogWjWorldCosmetic, Warning, TEXT("AddPromoItem: Steam 미지원 환경"));
   404→	return false;
   405→#endif
   406→}
   407→
   408→bool UWjWorldCosmeticSubsystem::AddAllPromoItems()
   409→{
   410→#if WITH_STEAM
   411→	ISteamInventory* SteamInv = SteamInventory();
   412→	if (!SteamInv)
   413→	{
   414→		UE_LOG(LogWjWorldCosmetic, Warning, TEXT("AddAllPromoItems: Steam Inventory API 사용 불가"));
   415→		return false;
   416→	}
   417→
   418→	SteamInventoryResult_t ResultHandle = k_SteamInventoryResultInvalid;
   419→
   420→	if (SteamInv->AddPromoItems(&ResultHandle, nullptr, 0))
   421→	{
   422→		UE_LOG(LogWjWorldCosmetic, Log, TEXT("AddAllPromoItems: 모든 프로모 아이템 지급 요청 성공"));
   423→
   424→		SteamInv->DestroyResult(ResultHandle);
   425→		RequestInventoryRefresh();
   426→		return true;
   427→	}
   428→	else
   429→	{
   430→		UE_LOG(LogWjWorldCosmetic, Warning, TEXT("AddAllPromoItems: Steam AddPromoItems 실패"));
   431→		return false;
   432→	}
   433→#else
   434→	UE_LOG(LogWjWorldCosmetic, Warning, TEXT("AddAllPromoItems: Steam 미지원 환경"));
   435→	return false;
   436→#endif
   437→}
