   439→bool UWjWorldCosmeticSubsystem::GenerateTestItem(FName ItemId)
   440→{
   441→#if WITH_STEAM && !UE_BUILD_SHIPPING
   442→	if (ItemId.IsNone())
   443→	{
   444→		UE_LOG(LogWjWorldCosmetic, Warning, TEXT("GenerateTestItem: 유효하지 않은 ItemId"));
   445→		return false;
   446→	}
   447→
   448→	ISteamInventory* SteamInv = SteamInventory();
   449→	if (!SteamInv)
   450→	{
   451→		UE_LOG(LogWjWorldCosmetic, Warning, TEXT("GenerateTestItem: Steam Inventory API 사용 불가"));
   452→		return false;
   453→	}
   454→
   455→	if (!Catalog)
   456→	{
   457→		UE_LOG(LogWjWorldCosmetic, Warning, TEXT("GenerateTestItem: 카탈로그 없음"));
   458→		return false;
   459→	}
   460→
   461→	int32 SteamDefId = Catalog->ItemIdToSteamItemDefId(ItemId);
   462→	if (SteamDefId == 0)
   463→	{
   464→		UE_LOG(LogWjWorldCosmetic, Warning, TEXT("GenerateTestItem: SteamItemDefId를 찾을 수 없음 (%s)"), *ItemId.ToString());
   465→		return false;
   466→	}
   467→
   468→	SteamItemDef_t ItemDef = static_cast<SteamItemDef_t>(SteamDefId);
   469→	uint32 Quantity = 1;
   470→	SteamInventoryResult_t ResultHandle = k_SteamInventoryResultInvalid;
   471→
   472→	if (SteamInv->GenerateItems(&ResultHandle, &ItemDef, &Quantity, 1))
   473→	{
   474→		UE_LOG(LogWjWorldCosmetic, Log, TEXT("GenerateTestItem: 테스트 아이템 생성 요청 성공 (%s, DefId: %d)"), *ItemId.ToString(), SteamDefId);
   475→
   476→		// 결과 핸들 정리 (비동기이므로 즉시 파괴하면 안됨 - 실제 구현시 폴링 필요)
   477→		// 간단한 테스트를 위해 로컬 인벤토리에도 추가
   478→		GrantItemLocally(ItemId, 1);
   479→
   480→		SteamInv->DestroyResult(ResultHandle);
   481→		return true;
   482→	}
   483→	else
   484→	{
   485→		UE_LOG(LogWjWorldCosmetic, Warning, TEXT("GenerateTestItem: Steam GenerateItems 실패"));
   486→		return false;
   487→	}
   488→#else
   489→	// 비 Steam 또는 Shipping 빌드: 로컬로 아이템 부여
   490→	UE_LOG(LogWjWorldCosmetic, Log, TEXT("GenerateTestItem: 로컬 아이템 부여 (비Steam 환경) - %s"), *ItemId.ToString());
   491→	GrantItemLocally(ItemId, 1);
   492→	return true;
   493→#endif
   494→}
   495→
   496→void UWjWorldCosmeticSubsystem::GrantAllItemsLocally()
   497→{
   498→#if !UE_BUILD_SHIPPING
   499→	if (!Catalog)
   500→	{
   501→		UE_LOG(LogWjWorldCosmetic, Warning, TEXT("GrantAllItemsLocally: 카탈로그 없음"));
   502→		return;
   503→	}
   504→
   505→	int32 GrantedCount = 0;
   506→	for (const FCosmeticItemDefinition& Def : Catalog->Items)
   507→	{
   508→		if (Def.IsValid() && !HasItem(Def.ItemId))
   509→		{
   510→			GrantItemLocally(Def.ItemId, 1);
   511→			GrantedCount++;
   512→		}
   513→	}
   514→
   515→	UE_LOG(LogWjWorldCosmetic, Log, TEXT("GrantAllItemsLocally: %d개 아이템 부여 완료"), GrantedCount);
   516→#endif
