   449→		}
   450→	}
   451→
   452→	if (CachedGemInstanceId != k_SteamItemInstanceIDInvalid && GemBalance > 0)
   453→	{
   454→		SteamInventoryResult_t ResultHandle = k_SteamInventoryResultInvalid;
   455→		if (SteamInv->ConsumeItem(&ResultHandle, CachedGemInstanceId, static_cast<uint32>(GemBalance)))
   456→		{
   457→			UE_LOG(LogWjWorldCurrency, Log, TEXT("Steam Gem 소비 요청 성공: %d개 (InstanceId=%llu)"), GemBalance, CachedGemInstanceId);
