   467→	UWjWorldCosmeticSubsystem* CosmeticSub = GetGameInstance()->GetSubsystem<UWjWorldCosmeticSubsystem>();
   468→	if (CosmeticSub)
   469→	{
   470→		CosmeticSub->RequestInventoryRefresh();
   471→	}
   472→#else
