   477→void UWjWorldCurrencySubsystem::DebugConsumeAllSteamItems()
   478→{
   479→#if WITH_STEAM
   480→	ISteamInventory* SteamInv = SteamInventory();
   481→	if (!SteamInv)
   482→	{
   483→		UE_LOG(LogWjWorldCurrency, Warning, TEXT("DebugConsumeAllSteamItems: Steam Inventory API 없음"));
   484→		return;
   485→	}
   486→
   487→	SteamInventoryResult_t AllItemsHandle = k_SteamInventoryResultInvalid;
   488→	if (!SteamInv->GetAllItems(&AllItemsHandle))
   489→	{
   490→		UE_LOG(LogWjWorldCurrency, Warning, TEXT("DebugConsumeAllSteamItems: GetAllItems 실패"));
   491→		return;
   492→	}
   493→
   494→	EResult Status = SteamInv->GetResultStatus(AllItemsHandle);
   495→	if (Status != k_EResultOK)
   496→	{
   497→		SteamInv->DestroyResult(AllItemsHandle);
   498→		UE_LOG(LogWjWorldCurrency, Warning, TEXT("DebugConsumeAllSteamItems: GetAllItems 상태 실패 (%d)"), static_cast<int32>(Status));
   499→		return;
   500→	}
   501→
   502→	uint32 ItemCount = 0;
   503→	if (!SteamInv->GetResultItems(AllItemsHandle, nullptr, &ItemCount) || ItemCount == 0)
   504→	{
   505→		SteamInv->DestroyResult(AllItemsHandle);
   506→		UE_LOG(LogWjWorldCurrency, Log, TEXT("DebugConsumeAllSteamItems: 인벤토리가 이미 비어있음"));
   507→		return;
   508→	}
   509→
   510→	TArray<SteamItemDetails_t> Items;
   511→	Items.SetNum(ItemCount);
   512→	SteamInv->GetResultItems(AllItemsHandle, Items.GetData(), &ItemCount);
   513→	SteamInv->DestroyResult(AllItemsHandle);
   514→
   515→	int32 ConsumedCount = 0;
   516→	for (const SteamItemDetails_t& Detail : Items)
   517→	{
   518→		if (Detail.m_unQuantity == 0)
   519→		{
   520→			continue;
   521→		}
   522→
   523→		SteamInventoryResult_t ConsumeHandle = k_SteamInventoryResultInvalid;
   524→		if (SteamInv->ConsumeItem(&ConsumeHandle, Detail.m_itemId, Detail.m_unQuantity))
   525→		{
   526→			UE_LOG(LogWjWorldCurrency, Log, TEXT("  소비: DefId=%d, Quantity=%d, InstanceId=%llu"),
   527→				Detail.m_iDefinition, Detail.m_unQuantity, Detail.m_itemId);
   528→			SteamInv->DestroyResult(ConsumeHandle);
   529→			++ConsumedCount;
   530→		}
   531→	}
   532→
   533→	// 캐시 초기화
   534→	CachedCoinInstanceId = k_SteamItemInstanceIDInvalid;
   535→	CachedGemInstanceId = k_SteamItemInstanceIDInvalid;
   536→
   537→	// 인벤토리 갱신
   538→	UWjWorldCosmeticSubsystem* CosmeticSub = GetGameInstance()->GetSubsystem<UWjWorldCosmeticSubsystem>();
   539→	if (CosmeticSub)
   540→	{
   541→		CosmeticSub->RequestInventoryRefresh();
   542→	}
   543→
   544→	UE_LOG(LogWjWorldCurrency, Log, TEXT("DebugConsumeAllSteamItems: %d/%d 아이템 소비 완료"), ConsumedCount, ItemCount);
   545→#else
   546→	UE_LOG(LogWjWorldCurrency, Warning, TEXT("DebugConsumeAllSteamItems: Steam 환경에서만 사용 가능"));
   547→#endif
   548→}
