   611→void UWjWorldCurrencySubsystem::StartExchangePolling()
   612→{
   613→	UWorld* World = GetWorld();
   614→	if (!World)
   615→	{
   616→		return;
   617→	}
   618→
   619→	World->GetTimerManager().SetTimer(
   620→		ExchangePollTimerHandle,
   621→		this,
   622→		&UWjWorldCurrencySubsystem::PollExchangeResult,
   623→		0.5f,
   624→		true
   625→	);
   626→}
