   637→void UWjWorldCurrencySubsystem::PollGemPurchaseResult()
   638→{
   639→#if WITH_STEAM
   640→	if (!bGemPurchasePending)
   641→	{
   642→		StopGemPurchasePolling();
   643→		return;
   644→	}
   645→
   646→	// Gem 팩 구매는 Steam 오버레이를 통해 처리되므로
   647→	// 인벤토리 변경을 감지하여 완료 판단
   648→	// CosmeticSubsystem의 OnInventoryUpdated → HandleInventoryUpdated → RefreshBalancesFromInventory
   649→	// 에서 Gem 잔액 변경이 감지되면 구매 완료로 판단
   650→
   651→	// 간단한 타임아웃 처리 (300초)
   652→	UWorld* World = GetWorld();
   653→	if (World)
   654→	{
   655→		if (GemPurchaseStartTime == 0.0f)
   656→		{
   657→			GemPurchaseStartTime = World->GetTimeSeconds();
   658→		}
   659→
   660→		float ElapsedTime = World->GetTimeSeconds() - GemPurchaseStartTime;
   661→		if (ElapsedTime > 300.0f)
   662→		{
   663→			UE_LOG(LogWjWorldCurrency, Warning, TEXT("Gem 팩 구매 타임아웃"));
   664→			bGemPurchasePending = false;
   665→			GemPurchaseStartTime = 0.0f;
   666→			StopGemPurchasePolling();
   667→		}
   668→	}
   669→#else
   670→	StopGemPurchasePolling();
   671→#endif
   672→}
   673→
