   709→void UWjWorldCurrencySubsystem::LoadBalancesFromLocal()
   710→{
   711→	int32 LoadedCoin = 0;
   712→	int32 LoadedGem = 0;
   713→
   714→	GConfig->GetInt(*CurrencyConfigSection, TEXT("CoinBalance"), LoadedCoin, GGameUserSettingsIni);
   715→	GConfig->GetInt(*CurrencyConfigSection, TEXT("GemBalance"), LoadedGem, GGameUserSettingsIni);
