   117→void UWjWorldPlacementComponent::SelectObject(FName ObjectId)
   118→{
   119→	if (!Catalog)
   120→	{
   121→		UE_LOG(LogWjWorldPlacement, Warning, TEXT("PlacementComponent: No catalog set"));
   122→		return;
   123→	}
   124→
   125→	const FPlaceableObjectDefinition* Def = Catalog->FindByObjectId(ObjectId);
   126→	if (!Def)
   127→	{
   128→		UE_LOG(LogWjWorldPlacement, Warning, TEXT("PlacementComponent: ObjectId=%s not found in catalog"), *ObjectId.ToString());
   129→		return;
   130→	}
   131→
   132→	// 삭제 모드에서 선택하면 배치 모드로 전환
   133→	if (CurrentMode == EPlacementMode::Deleting)
   134→	{
   135→		if (HoveredObject)
   136→		{
   137→			HoveredObject->SetHighlighted(false);
   138→			HoveredObject = nullptr;
   139→		}
   140→		CurrentMode = EPlacementMode::Placing;
   141→		OnPlacementModeChanged.Broadcast(CurrentMode);
   142→	}
   143→
   144→	// 기존 프리뷰 제거 후 새로 생성
   145→	DestroyPreview();
   146→	SelectedObjectId = ObjectId;
   147→
   148→	UWorld* World = GetWorld();
   149→	if (World)
   150→	{
   151→		FActorSpawnParameters SpawnParams;
   152→		SpawnParams.SpawnCollisionHandlingOverride = ESpawnActorCollisionHandlingMethod::AlwaysSpawn;
   153→		PreviewActor = World->SpawnActor<AWjWorldPlacementPreviewActor>(AWjWorldPlacementPreviewActor::StaticClass(), FVector::ZeroVector, FRotator::ZeroRotator, SpawnParams);
   154→		if (PreviewActor)
   155→		{
   156→			PreviewActor->InitializePreview(*Def);
   157→			UE_LOG(LogWjWorldPlacement, Log, TEXT("PlacementComponent: Preview created for ObjectId=%s"), *ObjectId.ToString());
   158→		}
   159→	}
   160→}
