   415→bool UWjWorldPlacementComponent::LoadLayoutFromSlot(const FString& SlotName)
   416→{
   417→	UWorld* World = GetWorld();
   418→	if (!World)
   419→	{
   420→		return false;
   421→	}
   422→
   423→	// SaveGame 로드
   424→	UWjWorldLayoutSaveGame* SaveGame = Cast<UWjWorldLayoutSaveGame>(
   425→		UGameplayStatics::LoadGameFromSlot(SlotName, 0)
   426→	);
   427→
   428→	if (!SaveGame)
   429→	{
   430→		UE_LOG(LogWjWorldPlacement, Warning, TEXT("PlacementComponent: Failed to load layout from '%s'"), *SlotName);
   431→		return false;
   432→	}
   433→
   434→	// 컨텍스트 검증 (다른 컨텍스트의 레이아웃 로드 방지)
   435→	if (SaveGame->SavedContext != EPlacementContext::None && SaveGame->SavedContext != CurrentContext)
   436→	{
   437→		UE_LOG(LogWjWorldPlacement, Warning, TEXT("PlacementComponent: Context mismatch - slot '%s' is for '%s', current context is '%s'"),
   438→			*SlotName, *GetPlacementContextName(SaveGame->SavedContext), *GetPlacementContextName(CurrentContext));
   439→		return false;
   440→	}
   441→
   442→	// DataProvider가 있으면 데이터 설정
   443→	IWjWorldPlacementDataProvider* DataProvider = GetPlacementDataProvider();
   444→	if (DataProvider)
   445→	{
   446→		// 일괄 설정 (RespawnAllPlacedObjects가 한 번만 호출됨)
   447→		DataProvider->SetPlacedObjects(SaveGame->PlacedObjects);
   448→	}
   449→
   450→	LoadedSlotName = SlotName;
   451→
   452→	// 로드된 오브젝트에 배치 모드 비주얼 적용
   453→	RefreshPlacementModeVisuals();
   454→
   455→	UE_LOG(LogWjWorldPlacement, Log, TEXT("PlacementComponent: Layout loaded from '%s' (%d objects)"),
   456→		*SlotName, SaveGame->PlacedObjects.Num());
   457→	return true;
   458→}
