   460→TArray<FString> UWjWorldPlacementComponent::GetSavedLayoutSlots() const
   461→{
   462→	TArray<FString> SlotNames;
   463→
   464→	// SaveGame 디렉토리에서 모든 .sav 파일 검색
   465→	FString SaveDirectory = FPaths::ProjectSavedDir() / TEXT("SaveGames");
   466→
   467→	IFileManager& FileManager = IFileManager::Get();
   468→	TArray<FString> FoundFiles;
   469→	FileManager.FindFiles(FoundFiles, *SaveDirectory, TEXT("*.sav"));
   470→
   471→	for (const FString& FileName : FoundFiles)
   472→	{
   473→		// .sav 확장자 제거하여 슬롯 이름 추출
   474→		FString SlotName = FPaths::GetBaseFilename(FileName);
   475→
   476→		// SaveGame을 로드하여 컨텍스트 확인
   477→		UWjWorldLayoutSaveGame* SaveGame = Cast<UWjWorldLayoutSaveGame>(
   478→			UGameplayStatics::LoadGameFromSlot(SlotName, 0)
   479→		);
   480→
   481→		if (SaveGame && SaveGame->SavedContext == CurrentContext)
   482→		{
   483→			SlotNames.Add(SlotName);
   484→		}
   485→	}
   486→
   487→	UE_LOG(LogWjWorldPlacement, Log, TEXT("PlacementComponent: Found %d saved layout slots for context '%s'"),
   488→		SlotNames.Num(), *GetPlacementContextName(CurrentContext));
   489→	return SlotNames;
   490→}
