   735→void UWjWorldPlacementComponent::TickComponent(float DeltaTime, ELevelTick TickType, FActorComponentTickFunction* ThisTickFunction)
   736→{
   737→	Super::TickComponent(DeltaTime, TickType, ThisTickFunction);
   738→
   739→	if (CurrentMode == EPlacementMode::Placing && PreviewActor)
   740→	{
   741→		const FPlaceableObjectDefinition* Def = Catalog ? Catalog->FindByObjectId(SelectedObjectId) : nullptr;
   742→		float GroundOffset = Def ? Def->GroundOffset : 0.0f;
   743→		FVector PlaceLocation;
   744→		bool bTraceSuccess = false;
   745→
   746→		if (bAirPlacementMode)
   747→		{
   748→			// Air 모드: 수평 평면과 교차
   749→			FVector AirLocation;
   750→			if (TraceAirPlane(AirLocation))
   751→			{
   752→				PlaceLocation = AirLocation + FVector(0.0f, 0.0f, GroundOffset);
   753→				bTraceSuccess = true;
   754→			}
   755→		}
   756→		else
   757→		{
   758→			// Ground 모드: 기존 바닥 트레이스
   759→			FHitResult HitResult;
   760→			if (TraceGroundUnderMouse(HitResult))
   761→			{
   762→				PlaceLocation = HitResult.ImpactPoint + FVector(0.0f, 0.0f, GroundOffset);
   763→				bTraceSuccess = true;
   764→			}
   765→		}
   766→
   767→		if (bTraceSuccess)
   768→		{
   769→			// AW 컨텍스트: 그리드 스냅 적용
   770→			if (CurrentContext == EPlacementContext::ApproachingWall)
   771→			{
   772→				PlaceLocation = SnapToGrid(PlaceLocation);
   773→			}
   774→
   775→			FRotator PlaceRotation = PreviewActor->GetCurrentRotation();
   776→			PreviewActor->UpdatePreviewTransform(PlaceLocation, PlaceRotation);
   777→
   778→			// 유효성 검사
   779→			bCurrentPreviewValid = IsPlacementLocationValid(PlaceLocation);
   780→			PreviewActor->SetPreviewValid(bCurrentPreviewValid);
   781→		}
   782→		else
   783→		{
   784→			bCurrentPreviewValid = false;
   785→			PreviewActor->SetPreviewValid(false);
   786→		}
   787→
   788→		// 3D 회전 축 기즈모 표시
   789→		DrawRotationAxisGizmo();
   790→	}
   791→
   792→	// JumpMap 컨텍스트: 체크포인트 위에 CheckpointOrder 번호 3D 표시
   793→	if (CurrentContext == EPlacementContext::JumpMap && CurrentMode != EPlacementMode::None)
   794→	{
   795→		IWjWorldPlacementDataProvider* DP = GetPlacementDataProvider();
   796→		if (DP)
   797→		{
   798→			for (const FPlacedObjectSaveEntry& Obj : DP->GetPlacedObjects())
   799→			{
   800→				if (Obj.ObjectId.ToString().Contains(TEXT("Checkpoint")))
   801→				{
   802→					const FString* OrderStr = Obj.CustomProperties.Find(TEXT("CheckpointOrder"));
   803→					if (OrderStr)
   804→					{
   805→						FVector TextLoc = Obj.Transform.GetLocation() + FVector(0, 0, 200.f);
   806→						DrawDebugString(GetWorld(), TextLoc,
   807→							FString::Printf(TEXT("CP #%s"), **OrderStr),
   808→							nullptr, FColor::Yellow, 0.f, true, 1.5f);
   809→					}
   810→				}
   811→			}
   812→		}
   813→	}
   814→
   815→	if (CurrentMode == EPlacementMode::Deleting)
   816→	{
   817→		// 삭제 모드: 호버 대상 갱신
   818→		AWjWorldPlacedObjectActor* NewHovered = TraceForPlacedObject();
   819→
   820→		if (NewHovered != HoveredObject)
   821→		{
   822→			if (HoveredObject)
   823→			{
   824→				HoveredObject->SetHighlighted(false);
   825→			}
   826→			HoveredObject = NewHovered;
   827→			if (HoveredObject)
   828→			{
   829→				HoveredObject->SetHighlighted(true);
   830→			}
   831→		}
   832→	}
   833→}
