  1157→			EIC->BindAction(CancelAction, ETriggerEvent::Started, this, &UWjWorldPlacementComponent::OnCancelAction);
  1158→		}
  1159→		if (RotateAction)
  1160→		{
  1161→			EIC->BindAction(RotateAction, ETriggerEvent::Started, this, &UWjWorldPlacementComponent::OnRotateAction);
  1162→		}
  1163→		if (DeleteAction)
  1164→		{
  1165→			EIC->BindAction(DeleteAction, ETriggerEvent::Started, this, &UWjWorldPlacementComponent::OnDeleteAction);
  1166→		}
  1167→		if (ScrollAction)
  1168→		{
  1169→			EIC->BindAction(ScrollAction, ETriggerEvent::Triggered, this, &UWjWorldPlacementComponent::OnScrollAction);
  1170→		}
  1171→		if (ToggleAirModeAction)
  1172→		{
  1173→			EIC->BindAction(ToggleAirModeAction, ETriggerEvent::Started, this, &UWjWorldPlacementComponent::OnToggleAirModeAction);
  1174→		}
  1175→		if (CycleAxisAction)
  1176→		{
  1177→			EIC->BindAction(CycleAxisAction, ETriggerEvent::Started, this, &UWjWorldPlacementComponent::OnCycleAxisAction);
  1178→		}
  1179→		if (CycleSnapAction)
  1180→		{
  1181→			EIC->BindAction(CycleSnapAction, ETriggerEvent::Started, this, &UWjWorldPlacementComponent::OnCycleSnapAction);
  1182→		}
  1183→	}
  1184→}
