  1238→	else if (CurrentMode == EPlacementMode::Placing)
  1239→	{
  1240→		ToggleDeleteMode();
  1241→	}
  1242→}
  1243→
  1244→void UWjWorldPlacementComponent::OnScrollAction(const FInputActionValue& Value)
  1245→{
  1246→	if (CurrentMode != EPlacementMode::Placing || !bAirPlacementMode)
  1247→	{
  1248→		return;
  1249→	}
  1250→
  1251→	float ScrollValue = Value.Get<float>();
  1252→	AirPlaneHeight += ScrollValue * AirHeightStep;
