  1273→
  1274→void UWjWorldPlacementComponent::ToggleAirPlacementMode()
  1275→{
  1276→	bAirPlacementMode = !bAirPlacementMode;
  1277→
  1278→	if (bAirPlacementMode && PreviewActor)
  1279→	{
  1280→		// 현재 프리뷰 위치의 Z를 초기 높이로 설정
  1281→		AirPlaneHeight = PreviewActor->GetActorLocation().Z;
  1282→	}
  1283→
  1284→	OnAirModeChanged.Broadcast(bAirPlacementMode);
  1285→	UE_LOG(LogWjWorldPlacement, Log, TEXT("PlacementComponent: Air mode %s (Height: %.0f)"),
  1286→		bAirPlacementMode ? TEXT("ON") : TEXT("OFF"), AirPlaneHeight);
  1287→}
