  1292→}
  1293→
  1294→IWjWorldPlacementDataProvider* UWjWorldPlacementComponent::GetPlacementDataProvider() const
  1295→{
  1296→	UWorld* World = GetWorld();
  1297→	if (!World)
  1298→	{
  1299→		return nullptr;
  1300→	}
  1301→
  1302→	// GameState에서 인터페이스 구현체 검색
  1303→	AGameStateBase* GameState = World->GetGameState();
  1304→	if (!GameState)
  1305→	{
  1306→		return nullptr;
  1307→	}
  1308→
  1309→	return Cast<IWjWorldPlacementDataProvider>(GameState);
  1310→}
  1311→
  1312→AWjWorldGameStateLobby* UWjWorldPlacementComponent::GetLobbyGameState() const
  1313→{
  1314→	UWorld* World = GetWorld();
