  1316→	{
  1317→		return nullptr;
  1318→	}
  1319→
  1320→	return World->GetGameState<AWjWorldGameStateLobby>();
  1321→}
  1322→
  1323→int32 UWjWorldPlacementComponent::FindPlacedObjectIndex(AWjWorldPlacedObjectActor* Actor) const
  1324→{
  1325→	if (!Actor)
  1326→	{
  1327→		return INDEX_NONE;
  1328→	}
  1329→
  1330→	IWjWorldPlacementDataProvider* DataProvider = GetPlacementDataProvider();
  1331→	if (!DataProvider)
  1332→	{
  1333→		return INDEX_NONE;
  1334→	}
  1335→
  1336→	const TArray<FPlacedObjectSaveEntry>& PlacedObjects = DataProvider->GetPlacedObjects();
  1337→	FName TargetId = Actor->GetObjectId();
  1338→	FVector TargetLocation = Actor->GetActorLocation();
  1339→
  1340→	// ObjectId와 위치로 매칭 (동일 ObjectId가 여러 개 있을 수 있으므로 위치도 체크)
  1341→	for (int32 i = 0; i < PlacedObjects.Num(); ++i)
  1342→	{
  1343→		const FPlacedObjectSaveEntry& Entry = PlacedObjects[i];
  1344→		if (Entry.ObjectId == TargetId)
  1345→		{
  1346→			// 위치가 가까우면 매치
  1347→			if (FVector::DistSquared(Entry.Transform.GetLocation(), TargetLocation) < 100.0f)
  1348→			{
  1349→				return i;
  1350→			}
  1351→		}
  1352→	}
  1353→
  1354→	return INDEX_NONE;
  1355→}
  1356→
  1357→bool UWjWorldPlacementComponent::ValidateJumpMapLayout(FString& OutErrorMessage) const
  1358→{
  1359→	IWjWorldPlacementDataProvider* DataProvider = GetPlacementDataProvider();
  1360→	if (!DataProvider)
  1361→	{
  1362→		OutErrorMessage = TEXT("Data provider not found");
  1363→		return false;
  1364→	}
  1365→
  1366→	const TArray<FPlacedObjectSaveEntry>& Objects = DataProvider->GetPlacedObjects();
  1367→
  1368→	int32 CheckpointCount = 0;
  1369→	int32 EndCount = 0;
  1370→
  1371→	for (const FPlacedObjectSaveEntry& Entry : Objects)
  1372→	{
  1373→		FString IdStr = Entry.ObjectId.ToString();
  1374→		if (IdStr.Contains(TEXT("Checkpoint")))
  1375→		{
  1376→			CheckpointCount++;
  1377→		}
  1378→		else if (IdStr.Contains(TEXT("End")))
  1379→		{
  1380→			EndCount++;
  1381→		}
  1382→	}
  1383→
  1384→	if (CheckpointCount < 1)
  1385→	{
  1386→		OutErrorMessage = TEXT("체크포인트가 최소 1개 필요합니다.");
  1387→		return false;
  1388→	}
  1389→
  1390→	if (EndCount != 1)
  1391→	{
  1392→		OutErrorMessage = FString::Printf(TEXT("도착점이 정확히 1개여야 합니다. (현재: %d개)"), EndCount);
  1393→		return false;
  1394→	}
  1395→
  1396→	return true;
  1397→}
