     3→#include "Cosmetic/WjWorldCosmeticSubsystem.h"
     4→#include "Cosmetic/WjWorldCosmeticDataAsset.h"
     5→#include "Setting/WjWorldDeveloperSettings.h"
     6→#include "WjWorldLogCategories.h"
     7→#include "Engine/World.h"
     8→#include "TimerManager.h"
     9→
    10→const FString UWjWorldCosmeticSubsystem::LoadoutConfigSection = TEXT("CosmeticLoadout");
    11→
    12→void UWjWorldCosmeticSubsystem::Initialize(FSubsystemCollectionBase& Collection)
    13→{
    14→	Super::Initialize(Collection);
    15→
    16→	// DeveloperSettings에서 카탈로그 로드
    17→	const UWjWorldDeveloperSettings* Settings = GetDefault<UWjWorldDeveloperSettings>();
    18→	if (Settings && !Settings->CosmeticCatalog.IsNull())
    19→	{
    20→		Catalog = Settings->CosmeticCatalog.LoadSynchronous();
    21→		UE_LOG(LogWjWorldCosmetic, Log, TEXT("카탈로그 로드: %s"), Catalog ? *Catalog->GetName() : TEXT("실패"));
    22→	}
    23→	else
    24→	{
    25→		UE_LOG(LogWjWorldCosmetic, Warning, TEXT("DeveloperSettings에 CosmeticCatalog가 설정되지 않았습니다."));
    26→	}
    27→
    28→	LoadLoadoutFromLocal();
    29→
    30→	// Steam 인벤토리 초기 로드
    31→	RequestInventoryRefresh();
    32→
    33→	UE_LOG(LogWjWorldCosmetic, Log, TEXT("CosmeticSubsystem 초기화 완료"));
    34→}
    35→
    36→void UWjWorldCosmeticSubsystem::Deinitialize()
    37→{
    38→	StopInventoryPolling();
    39→	SaveLoadoutToLocal();
    40→
    41→#if WITH_STEAM
    42→	// 대기 중인 결과 핸들 정리
    43→	if (PendingResultHandle != k_SteamInventoryResultInvalid)
    44→	{
    45→		ISteamInventory* SteamInv = SteamInventory();
    46→		if (SteamInv)
    47→		{
    48→			SteamInv->DestroyResult(PendingResultHandle);
    49→		}
    50→		PendingResultHandle = k_SteamInventoryResultInvalid;
    51→	}
    52→#endif
    53→
    54→	Super::Deinitialize();
    55→}
    56→
    57→void UWjWorldCosmeticSubsystem::SetCatalog(UWjWorldCosmeticCatalogDataAsset* InCatalog)
    58→{
    59→	Catalog = InCatalog;
    60→	UE_LOG(LogWjWorldCosmetic, Log, TEXT("카탈로그 설정: %s"), InCatalog ? *InCatalog->GetName() : TEXT("null"));
    61→}
    62→
    63→void UWjWorldCosmeticSubsystem::RequestInventoryRefresh()
    64→{
    65→	if (bInventoryRequestPending)
    66→	{
    67→		UE_LOG(LogWjWorldCosmetic, Log, TEXT("인벤토리 요청이 이미 진행 중입니다."));
    68→		return;
    69→	}
    70→
    71→#if WITH_STEAM
    72→	ISteamInventory* SteamInv = SteamInventory();
    73→	if (!SteamInv)
    74→	{
    75→		UE_LOG(LogWjWorldCosmetic, Warning, TEXT("Steam Inventory API를 사용할 수 없습니다."));
    76→		return;
    77→	}
    78→
    79→	// 기존 핸들 정리
    80→	if (PendingResultHandle != k_SteamInventoryResultInvalid)
    81→	{
    82→		SteamInv->DestroyResult(PendingResultHandle);
    83→		PendingResultHandle = k_SteamInventoryResultInvalid;
    84→	}
    85→
    86→	if (SteamInv->GetAllItems(&PendingResultHandle))
    87→	{
    88→		bInventoryRequestPending = true;
    89→		StartInventoryPolling();
    90→		UE_LOG(LogWjWorldCosmetic, Log, TEXT("Steam 인벤토리 요청 성공 (ResultHandle: %d)"), PendingResultHandle);
    91→	}
    92→	else
    93→	{
    94→		UE_LOG(LogWjWorldCosmetic, Warning, TEXT("Steam 인벤토리 요청 실패"));
    95→	}
    96→#else
    97→	UE_LOG(LogWjWorldCosmetic, Log, TEXT("Steam 미지원 환경 - 인벤토리 갱신 스킵"));
    98→	OnInventoryUpdated.Broadcast();
    99→#endif
   100→}
   101→
   102→bool UWjWorldCosmeticSubsystem::HasItem(FName ItemId) const
   103→{
   104→	return CachedInventory.ContainsByPredicate([ItemId](const FCosmeticItemInstance& Inst)
   105→	{
   106→		return Inst.ItemId == ItemId && Inst.Quantity > 0;
   107→	});
   108→}
   109→
   110→void UWjWorldCosmeticSubsystem::GrantItemLocally(FName ItemId, int32 Quantity)
   111→{
   112→	if (ItemId.IsNone() || Quantity <= 0)
   113→	{
   114→		return;
   115→	}
   116→
   117→	// 기존 아이템 수량 증가 또는 새로 추가
   118→	FCosmeticItemInstance* Existing = CachedInventory.FindByPredicate([ItemId](const FCosmeticItemInstance& Inst)
   119→	{
   120→		return Inst.ItemId == ItemId;
   121→	});
   122→
   123→	if (Existing)
   124→	{
   125→		Existing->Quantity += Quantity;
   126→	}
   127→	else
   128→	{
   129→		FCosmeticItemInstance NewItem(ItemId);
   130→		NewItem.Quantity = Quantity;
   131→		CachedInventory.Add(NewItem);
   132→	}
   133→
   134→	UE_LOG(LogWjWorldCosmetic, Log, TEXT("로컬 아이템 부여: %s x%d"), *ItemId.ToString(), Quantity);
   135→	OnInventoryUpdated.Broadcast();
   136→}
