   214→void UWjWorldCosmeticSubsystem::StartInventoryPolling()
   215→{
   216→	UWorld* World = GetWorld();
   217→	if (!World)
   218→	{
   219→		return;
   220→	}
   221→
   222→	// 100ms 간격으로 결과 폴링
   223→	World->GetTimerManager().SetTimer(
   224→		InventoryPollTimerHandle,
   225→		this,
   226→		&UWjWorldCosmeticSubsystem::PollSteamInventoryResult,
   227→		0.1f,
   228→		true
   229→	);
   230→
   231→	UE_LOG(LogWjWorldCosmetic, Log, TEXT("인벤토리 폴링 시작"));
   232→}
