   184→{
   185→	// 이미 Catalog가 설정되어 있으면 스킵
   186→	if (Catalog)
   187→	{
   188→		return;
   189→	}
   190→
   191→	// DeveloperSettings에서 Catalog 로드 (폴백 메커니즘)
   192→	const UWjWorldDeveloperSettings* Settings = GetDefault<UWjWorldDeveloperSettings>();
   193→	if (!Settings || Settings->LobbyPlaceableCatalog.IsNull())
   194→	{
   195→		UE_LOG(LogWjWorldPlacement, Warning, TEXT("GameStateLobby: No LobbyPlaceableCatalog configured in DeveloperSettings"));
   196→		return;
   197→	}
   198→
   199→	Catalog = Settings->LobbyPlaceableCatalog.LoadSynchronous();
   200→	if (Catalog)
   201→	{
   202→		UE_LOG(LogWjWorldPlacement, Log, TEXT("GameStateLobby: Catalog loaded from DeveloperSettings (fallback)"));
   203→	}
   204→	else
   205→	{
   206→		UE_LOG(LogWjWorldPlacement, Error, TEXT("GameStateLobby: Failed to load LobbyPlaceableCatalog"));
   207→	}
   208→}
