   533→
   534→bool UWjWorldPlacementComponent::ExportLayoutAsCSV(const FString& FileName)
   535→{
   536→	// AW 컨텍스트에서만 동작
   537→	if (CurrentContext != EPlacementContext::ApproachingWall)
   538→	{
   539→		UE_LOG(LogWjWorldPlacement, Warning, TEXT("ExportLayoutAsCSV: Only available in ApproachingWall context"));
   540→		return false;
   541→	}
   542→
   543→	IWjWorldPlacementDataProvider* DataProvider = GetPlacementDataProvider();
   544→	if (!DataProvider)
   545→	{
   546→		UE_LOG(LogWjWorldPlacement, Error, TEXT("ExportLayoutAsCSV: No data provider"));
   547→		return false;
   548→	}
   549→
   550→	const TArray<FPlacedObjectSaveEntry>& PlacedObjects = DataProvider->GetPlacedObjects();
   551→	if (PlacedObjects.Num() == 0)
   552→	{
   553→		UE_LOG(LogWjWorldPlacement, Warning, TEXT("ExportLayoutAsCSV: No objects to export"));
   554→		return false;
   555→	}
   556→
   557→	// 그리드 설정 (기본값 사용, 추후 설정 가능하게 확장 가능)
   558→	const FApproachingWallGridConfig GridConfig;
   559→	const FVector& BrickSize = GridConfig.BrickSize;
   560→
   561→	// 1. 배치된 오브젝트의 바운딩 박스 계산
   562→	FVector MinBounds(FLT_MAX, FLT_MAX, FLT_MAX);
   563→	FVector MaxBounds(-FLT_MAX, -FLT_MAX, -FLT_MAX);
   564→
   565→	for (const FPlacedObjectSaveEntry& Entry : PlacedObjects)
   566→	{
   567→		const FVector& Location = Entry.Transform.GetLocation();
   568→		MinBounds.X = FMath::Min(MinBounds.X, Location.X);
   569→		MinBounds.Y = FMath::Min(MinBounds.Y, Location.Y);
   570→		MaxBounds.X = FMath::Max(MaxBounds.X, Location.X);
   571→		MaxBounds.Y = FMath::Max(MaxBounds.Y, Location.Y);
   572→	}
   573→
   574→	// 2. 그리드 크기 계산 (+1 = 위치 개수, +2 = 양쪽 1셀 패딩)
   575→	int32 GridColumns = FMath::CeilToInt((MaxBounds.X - MinBounds.X) / BrickSize.X) + 1 + 2;
   576→	int32 GridRows = FMath::CeilToInt((MaxBounds.Y - MinBounds.Y) / BrickSize.Y) + 1 + 2;
   577→
   578→	// 최소 크기 보장
   579→	GridColumns = FMath::Max(GridColumns, 3);
   580→	GridRows = FMath::Max(GridRows, 3);
   581→
   582→	// 그리드 원점: MinBounds에서 1칸 앞 (패딩용, 오브젝트가 인덱스 1부터 매핑)
   583→	FVector GridOrigin = MinBounds - FVector(BrickSize.X, BrickSize.Y, 0.0f);
   584→
   585→	// 3. 그리드 초기화 (-1 = Empty)
   586→	TArray<TArray<int32>> Grid;
   587→	Grid.SetNum(GridRows);
   588→	for (int32 Row = 0; Row < GridRows; ++Row)
   589→	{
   590→		Grid[Row].SetNum(GridColumns);
   591→		for (int32 Col = 0; Col < GridColumns; ++Col)
   592→		{
   593→			Grid[Row][Col] = -1;
   594→		}
   595→	}
   596→
   597→	// 4. 오브젝트를 그리드에 매핑 (RoundToInt로 CalculateBrickGridIndex와 일치)
   598→	for (const FPlacedObjectSaveEntry& Entry : PlacedObjects)
   599→	{
   600→		const FVector& Location = Entry.Transform.GetLocation();
   601→
   602→		// 월드 좌표 → 그리드 인덱스
   603→		int32 Col = FMath::RoundToInt((Location.X - GridOrigin.X) / BrickSize.X);
   604→		int32 Row = FMath::RoundToInt((Location.Y - GridOrigin.Y) / BrickSize.Y);
   605→
   606→		// 범위 체크
   607→		if (Row >= 0 && Row < GridRows && Col >= 0 && Col < GridColumns)
   608→		{
   609→			int32 BrickTypeValue = ObjectIdToBrickTypeValue(Entry.ObjectId);
   610→			Grid[Row][Col] = BrickTypeValue;
   611→		}
   612→	}
   613→
   614→	// 5. CSV 문자열 생성 (첫 줄에 메타데이터 포함)
   615→	FString CSVContent;
   616→
   617→	// ⭐ 메타데이터 헤더: CenterOffset 저장 (클라이언트 프리뷰 위치 동기화용)
   618→	// CalculateBrickPosition은 CenterOffset을 그리드 중심으로 사용하므로, 그리드 중심 좌표를 저장
   619→	FVector CenterOffset;
   620→	CenterOffset.X = GridOrigin.X + (GridColumns - 1) * 0.5f * BrickSize.X;
   621→	CenterOffset.Y = GridOrigin.Y + (GridRows - 1) * 0.5f * BrickSize.Y;
   622→	CenterOffset.Z = 0.0f;
   623→	CSVContent += FString::Printf(TEXT("#META:CenterOffset:%f,%f,%f\n"),
   624→		CenterOffset.X, CenterOffset.Y, CenterOffset.Z);
   625→
   626→	for (int32 Row = 0; Row < GridRows; ++Row)
   627→	{
   628→		for (int32 Col = 0; Col < GridColumns; ++Col)
   629→		{
   630→			CSVContent += FString::Printf(TEXT("%d"), Grid[Row][Col]);
   631→			if (Col < GridColumns - 1)
   632→			{
   633→				CSVContent += TEXT(",");
   634→			}
   635→		}
   636→		CSVContent += TEXT("\n");
   637→	}
   638→
   639→	// 6. 파일 저장
   640→	FString UserLayoutDir = GetUserWallLayoutDirectory();
   641→
   642→	// 디렉토리 생성
   643→	IPlatformFile& PlatformFile = FPlatformFileManager::Get().GetPlatformFile();
   644→	if (!PlatformFile.DirectoryExists(*UserLayoutDir))
   645→	{
   646→		PlatformFile.CreateDirectoryTree(*UserLayoutDir);
   647→	}
   648→
   649→	FString FilePath = UserLayoutDir / FileName + TEXT(".csv");
   650→
   651→	if (FFileHelper::SaveStringToFile(CSVContent, *FilePath))
   652→	{
   653→		LastExportedCSVPath = FilePath;
   654→		UE_LOG(LogWjWorldPlacement, Log, TEXT("ExportLayoutAsCSV: Exported to '%s' (Grid: %dx%d)"),
   655→			*FilePath, GridColumns, GridRows);
   656→		return true;
   657→	}
   658→	else
   659→	{
   660→		UE_LOG(LogWjWorldPlacement, Error, TEXT("ExportLayoutAsCSV: Failed to save file '%s'"), *FilePath);
   661→		return false;
   662→	}
   663→}
