   665→bool UWjWorldPlacementComponent::ExportJumpMapLayoutAsCSV(const FString& FileName)
   666→{
   667→	if (CurrentContext != EPlacementContext::JumpMap)
   668→	{
   669→		UE_LOG(LogWjWorldPlacement, Warning, TEXT("ExportJumpMapLayoutAsCSV: Only available in JumpMap context"));
   670→		return false;
   671→	}
   672→
   673→	IWjWorldPlacementDataProvider* DataProvider = GetPlacementDataProvider();
   674→	if (!DataProvider)
   675→	{
   676→		UE_LOG(LogWjWorldPlacement, Error, TEXT("ExportJumpMapLayoutAsCSV: No data provider"));
   677→		return false;
   678→	}
   679→
   680→	const TArray<FPlacedObjectSaveEntry>& PlacedObjects = DataProvider->GetPlacedObjects();
   681→	if (PlacedObjects.Num() == 0)
   682→	{
   683→		UE_LOG(LogWjWorldPlacement, Warning, TEXT("ExportJumpMapLayoutAsCSV: No objects to export"));
   684→		return false;
   685→	}
   686→
   687→	// CSV 생성: 헤더 + 오브젝트 행 (11번째 Properties 컬럼 포함)
   688→	FString CSVContent;
   689→	CSVContent += FString::Printf(TEXT("#META:MapName:%s\n"), *FileName);
   690→	CSVContent += TEXT("ObjectId,PosX,PosY,PosZ,RotPitch,RotYaw,RotRoll,ScaleX,ScaleY,ScaleZ,Properties\n");
   691→
   692→	for (const FPlacedObjectSaveEntry& Entry : PlacedObjects)
   693→	{
   694→		const FVector& Loc = Entry.Transform.GetLocation();
   695→		const FRotator Rot = Entry.Transform.GetRotation().Rotator();
   696→		const FVector& Scale = Entry.Transform.GetScale3D();
   697→
   698→		// CustomProperties를 Key=Value|Key=Value 형식으로 직렬화
   699→		FString PropsStr;
   700→		for (const auto& Pair : Entry.CustomProperties)
   701→		{
   702→			if (!PropsStr.IsEmpty()) PropsStr += TEXT("|");
   703→			PropsStr += FString::Printf(TEXT("%s=%s"), *Pair.Key, *Pair.Value);
   704→		}
   705→
   706→		CSVContent += FString::Printf(TEXT("%s,%f,%f,%f,%f,%f,%f,%f,%f,%f,%s\n"),
   707→			*Entry.ObjectId.ToString(),
   708→			Loc.X, Loc.Y, Loc.Z,
   709→			Rot.Pitch, Rot.Yaw, Rot.Roll,
   710→			Scale.X, Scale.Y, Scale.Z,
   711→			*PropsStr);
   712→	}
   713→
   714→	// 파일 저장
   715→	FString UserLayoutDir = GetUserJumpMapLayoutDirectory();
   716→	IPlatformFile& PlatformFile = FPlatformFileManager::Get().GetPlatformFile();
   717→	if (!PlatformFile.DirectoryExists(*UserLayoutDir))
   718→	{
   719→		PlatformFile.CreateDirectoryTree(*UserLayoutDir);
   720→	}
   721→
   722→	FString FilePath = UserLayoutDir / FileName + TEXT(".csv");
   723→	if (FFileHelper::SaveStringToFile(CSVContent, *FilePath))
   724→	{
   725→		LastExportedCSVPath = FilePath;
   726→		UE_LOG(LogWjWorldPlacement, Log, TEXT("ExportJumpMapLayoutAsCSV: Exported to '%s' (%d objects)"),
   727→			*FilePath, PlacedObjects.Num());
   728→		return true;
   729→	}
   730→
   731→	UE_LOG(LogWjWorldPlacement, Error, TEXT("ExportJumpMapLayoutAsCSV: Failed to save '%s'"), *FilePath);
   732→	return false;
   733→}
