   835→bool UWjWorldPlacementComponent::TraceGroundUnderMouse(FHitResult& OutHit) const
   836→{
   837→	APlayerController* PC = GetPlayerController();
   838→	if (!PC)
   839→	{
   840→		return false;
   841→	}
   842→
   843→	FVector WorldLocation, WorldDirection;
   844→	if (!PC->DeprojectMousePositionToWorld(WorldLocation, WorldDirection))
   845→	{
   846→		return false;
   847→	}
   848→
   849→	FVector TraceEnd = WorldLocation + WorldDirection * TraceDistance;
   850→
   851→	FCollisionQueryParams QueryParams;
   852→	QueryParams.bTraceComplex = false;
   853→	QueryParams.AddIgnoredActor(GetOwner());
   854→	if (PreviewActor)
   855→	{
   856→		QueryParams.AddIgnoredActor(PreviewActor);
   857→	}
   858→
   859→	return GetWorld()->LineTraceSingleByChannel(OutHit, WorldLocation, TraceEnd, ECC_Visibility, QueryParams);
   860→}
   861→
   862→bool UWjWorldPlacementComponent::TraceAirPlane(FVector& OutLocation) const
   863→{
   864→	APlayerController* PC = GetPlayerController();
   865→	if (!PC)
   866→	{
   867→		return false;
   868→	}
   869→
   870→	FVector WorldLoc, WorldDir;
   871→	if (!PC->DeprojectMousePositionToWorld(WorldLoc, WorldDir))
   872→	{
   873→		return false;
   874→	}
   875→
   876→	// Ray-plane intersection: Plane at Z = AirPlaneHeight, Normal = UpVector
   877→	float Denom = FVector::DotProduct(WorldDir, FVector::UpVector);
   878→	if (FMath::Abs(Denom) < KINDA_SMALL_NUMBER)
   879→	{
   880→		return false; // 레이가 평면과 평행
   881→	}
   882→
   883→	float T = (AirPlaneHeight - WorldLoc.Z) / Denom;
   884→	if (T < 0.f || T > MaxAirTraceDistance)
   885→	{
   886→		return false; // 뒤쪽이거나 너무 먼 교차점
   887→	}
   888→
   889→	OutLocation = WorldLoc + WorldDir * T;
   890→	return true;
   891→}
   892→
   893→bool UWjWorldPlacementComponent::IsPlacementLocationValid(const FVector& Location) const
   894→{
   895→	UWorld* World = GetWorld();
   896→	if (!World)
   897→	{
   898→		return false;
   899→	}
   900→
   901→	// AW 컨텍스트: 그리드 스냅 사용 시 더 작은 반경으로 정확히 같은 위치만 체크
   902→	// 일반 컨텍스트: 기존 겹침 반경 사용
   903→	float CheckRadius = (CurrentContext == EPlacementContext::ApproachingWall)
   904→		? GridOverlapCheckRadius
   905→		: OverlapCheckRadius;
   906→
   907→	// 겹침 체크: 기존 배치된 오브젝트와 겹치는지
   908→	TArray<FOverlapResult> Overlaps;
   909→	FCollisionQueryParams QueryParams;
   910→	QueryParams.AddIgnoredActor(GetOwner());
   911→	if (PreviewActor)
   912→	{
   913→		QueryParams.AddIgnoredActor(PreviewActor);
   914→	}
   915→
   916→	FCollisionShape SphereShape = FCollisionShape::MakeSphere(CheckRadius);
   917→	World->OverlapMultiByChannel(Overlaps, Location, FQuat::Identity, ECC_Visibility, SphereShape, QueryParams);
   918→
   919→	for (const FOverlapResult& Overlap : Overlaps)
   920→	{
   921→		if (Cast<AWjWorldPlacedObjectActor>(Overlap.GetActor()))
   922→		{
   923→			return false;
   924→		}
   925→	}
   926→
   927→	return true;
   928→}
   929→
   930→FVector UWjWorldPlacementComponent::SnapToGrid(const FVector& Location) const
   931→{
   932→	// AW 그리드 설정 사용
   933→	const FApproachingWallGridConfig GridConfig;
   934→	const FVector& BrickSize = GridConfig.BrickSize;
   935→
   936→	// 그리드 스냅: 각 축을 BrickSize 단위로 반올림
   937→	FVector SnappedLocation;
   938→	SnappedLocation.X = FMath::RoundToFloat(Location.X / BrickSize.X) * BrickSize.X;
   939→	SnappedLocation.Y = FMath::RoundToFloat(Location.Y / BrickSize.Y) * BrickSize.Y;
   940→	SnappedLocation.Z = Location.Z; // Z축은 스냅하지 않음 (바닥 높이 유지)
   941→
   942→	return SnappedLocation;
   943→}
   944→
   945→AWjWorldPlacedObjectActor* UWjWorldPlacementComponent::TraceForPlacedObject() const
   946→{
   947→	APlayerController* PC = GetPlayerController();
   948→	if (!PC)
   949→	{
   950→		return nullptr;
   951→	}
   952→
   953→	FVector WorldLocation, WorldDirection;
   954→	if (!PC->DeprojectMousePositionToWorld(WorldLocation, WorldDirection))
   955→	{
   956→		return nullptr;
   957→	}
   958→
   959→	FVector TraceEnd = WorldLocation + WorldDirection * TraceDistance;
   960→
   961→	FHitResult HitResult;
   962→	FCollisionQueryParams QueryParams;
   963→	QueryParams.bTraceComplex = false;
   964→	QueryParams.AddIgnoredActor(GetOwner());
   965→
   966→	if (GetWorld()->LineTraceSingleByChannel(HitResult, WorldLocation, TraceEnd, ECC_Visibility, QueryParams))
   967→	{
