   990→void UWjWorldPlacementComponent::DrawRotationAxisGizmo() const
   991→{
   992→	UWorld* World = GetWorld();
   993→	if (!World || !PreviewActor)
   994→	{
   995→		return;
   996→	}
   997→
   998→	FVector Origin = PreviewActor->GetActorLocation();
   999→	FVector AxisDir;
  1000→	FColor AxisColor;
  1001→	FString AxisName;
  1002→
  1003→	switch (PreviewActor->GetCurrentRotationAxis())
  1004→	{
  1005→	case EPlacementRotationAxis::Yaw:
  1006→		AxisDir = FVector::UpVector;
  1007→		AxisColor = FColor::Blue;
  1008→		AxisName = TEXT("Yaw (Z)");
  1009→		break;
  1010→	case EPlacementRotationAxis::Pitch:
  1011→		AxisDir = FVector::RightVector;
  1012→		AxisColor = FColor::Green;
  1013→		AxisName = TEXT("Pitch (Y)");
  1014→		break;
  1015→	case EPlacementRotationAxis::Roll:
  1016→		AxisDir = FVector::ForwardVector;
  1017→		AxisColor = FColor::Red;
  1018→		AxisName = TEXT("Roll (X)");
  1019→		break;
  1020→	}
  1021→
  1022→	FVector ArrowEnd = Origin + AxisDir * GizmoArrowLength;
  1023→	DrawDebugDirectionalArrow(World, Origin, ArrowEnd, GizmoArrowSize, AxisColor, false, -1.f, 0, GizmoArrowThickness);
  1024→
  1025→	// 반대 방향 짧은 선분 (양방향 축 표현)
  1026→	FVector OppositeEnd = Origin - AxisDir * (GizmoArrowLength * 0.3f);
  1027→	DrawDebugLine(World, Origin, OppositeEnd, AxisColor, false, -1.f, 0, GizmoArrowThickness * 0.5f);
  1028→
  1029→	// 축 이름 + 스냅 각도 텍스트 표시
  1030→	FString InfoText = FString::Printf(TEXT("%s | %.0f°"), *AxisName, GetEffectiveSnapDegrees());
  1031→	DrawDebugString(World, ArrowEnd + FVector(0.f, 0.f, 15.f), InfoText, nullptr, AxisColor, 0.f, true, 1.f);
  1032→}
