  1357→bool UWjWorldPlacementComponent::ValidateJumpMapLayout(FString& OutErrorMessage) const
  1358→{
  1359→	IWjWorldPlacementDataProvider* DataProvider = GetPlacementDataProvider();
  1360→	if (!DataProvider)
  1361→	{
  1362→		OutErrorMessage = TEXT("Data provider not found");
  1363→		return false;
  1364→	}
  1365→
  1366→	const TArray<FPlacedObjectSaveEntry>& Objects = DataProvider->GetPlacedObjects();
  1367→
  1368→	int32 CheckpointCount = 0;
  1369→	int32 EndCount = 0;
  1370→
  1371→	for (const FPlacedObjectSaveEntry& Entry : Objects)
  1372→	{
  1373→		FString IdStr = Entry.ObjectId.ToString();
  1374→		if (IdStr.Contains(TEXT("Checkpoint")))
  1375→		{
  1376→			CheckpointCount++;
  1377→		}
  1378→		else if (IdStr.Contains(TEXT("End")))
  1379→		{
  1380→			EndCount++;
  1381→		}
  1382→	}
  1383→
  1384→	if (CheckpointCount < 1)
  1385→	{
  1386→		OutErrorMessage = TEXT("체크포인트가 최소 1개 필요합니다.");
  1387→		return false;
  1388→	}
  1389→
  1390→	if (EndCount != 1)
  1391→	{
  1392→		OutErrorMessage = FString::Printf(TEXT("도착점이 정확히 1개여야 합니다. (현재: %d개)"), EndCount);
  1393→		return false;
  1394→	}
  1395→
  1396→	return true;
  1397→}
