	TArray<FCurrencyBalance> GetAllBalances() const;

	// ---- 미니게임 보상 ----

	/** 미니게임 종료 시 보상 지급 (각 클라이언트에서 호출) */
	UFUNCTION(BlueprintCallable, Category = "Currency")
	void TriggerMatchReward(bool bIsWinner);

	// ---- 재화로 코스메틱 구매 ----

	/** 재화를 소비하여 코스메틱 아이템 구매 */
