void UPlacementHUDWidgetBase::OnCatalogItemClicked(FName ObjectId)
{
	if (!PlacementComponent)
	{
		return;
	}

	// 로비 컨텍스트: 미소유 유료 아이템 클릭 시 구매 시도
	if (GetCurrentContext() == EPlacementContext::Lobby)
	{
		UWjWorldPlaceableObjectDataAsset* Catalog = PlacementComponent->GetCatalog();
		if (Catalog)
		{
			const FPlaceableObjectDefinition* Def = Catalog->FindByObjectId(ObjectId);
			if (Def && Def->CoinPrice > 0 && Def->SteamItemDefId > 0)
			{
				UGameInstance* GI = GetGameInstance();
				UWjWorldCosmeticSubsystem* CosmeticSub = GI ? GI->GetSubsystem<UWjWorldCosmeticSubsystem>() : nullptr;
				int32 OwnedQty = CosmeticSub ? CosmeticSub->GetItemQuantityByDefId(Def->SteamItemDefId) : 0;

				if (OwnedQty <= 0)
				{
					// 미소유 → 구매 시도
					UWjWorldCurrencySubsystem* CurrencySub = GI ? GI->GetSubsystem<UWjWorldCurrencySubsystem>() : nullptr;
					if (CurrencySub)
					{
						CurrencySub->PurchasePlacementObject(ObjectId);
						UE_LOG(LogWjWorldPlacement, Log, TEXT("PlacementHUDWidgetBase: 구매 시도 %s"), *ObjectId.ToString());
					}
					return;
				}
			}
		}
	}

	PlacementComponent->SelectObject(ObjectId);
	UE_LOG(LogWjWorldPlacement, Log, TEXT("PlacementHUDWidgetBase: Selected object %s"), *ObjectId.ToString());
}

