void UPlacementHUDWidgetBase::SetPlacementComponent(UWjWorldPlacementComponent* InComponent)
{
	PlacementComponent = InComponent;

	if (PlacementComponent)
	{
		PopulateCatalog(PlacementComponent->GetCatalog());
	}
}

