	if (!CosmeticSub)
	{
		UE_LOG(LogWjWorld, Warning, TEXT("Cosmetic_GrantAll: CosmeticSubsystem 없음"));
		return;
	}

	CosmeticSub->GrantAllItemsLocally();
	UE_LOG(LogWjWorld, Log, TEXT("Cosmetic_GrantAll: 모든 아이템 부여 완료"));
#endif
}

