		return;
	}

	ECosmeticSlot Slot = static_cast<ECosmeticSlot>(SlotIndex);
	if (Slot == ECosmeticSlot::None || SlotIndex < 1 || SlotIndex > 4)
	{
		UE_LOG(LogWjWorld, Warning, TEXT("Cosmetic_Equip: 유효하지 않은 슬롯 (1=Head, 2=Body, 3=Back, 4=Effect)"));
