	}

	FName ItemFName(*ItemId);
	if (CosmeticSub->EquipItem(Slot, ItemFName))
	{
		CosmeticSub->SaveLoadoutToLocal();
		UE_LOG(LogWjWorld, Log, TEXT("Cosmetic_Equip: 슬롯 %d에 %s 장착 완료"), SlotIndex, *ItemId);
	}
#endif
}

