    14→void UWjWorldCosmeticSubsystem::Initialize(FSubsystemCollectionBase& Collection)
    15→{
    16→	Super::Initialize(Collection);
    17→
    18→	// DeveloperSettings에서 카탈로그 로드
    19→	const UWjWorldDeveloperSettings* Settings = GetDefault<UWjWorldDeveloperSettings>();
    20→	if (Settings && !Settings->CosmeticCatalog.IsNull())
    21→	{
    22→		Catalog = Settings->CosmeticCatalog.LoadSynchronous();
    23→		UE_LOG(LogWjWorldCosmetic, Log, TEXT("카탈로그 로드: %s"), Catalog ? *Catalog->GetName() : TEXT("실패"));
    24→	}
    25→	else
    26→	{
    27→		UE_LOG(LogWjWorldCosmetic, Warning, TEXT("DeveloperSettings에 CosmeticCatalog가 설정되지 않았습니다."));
    28→	}
    29→
    30→	LoadLoadoutFromLocal();
    31→	LoadPlacementInventoryFromLocal();
    32→
    33→	// Steam 인벤토리 초기 로드
    34→	RequestInventoryRefresh();
    35→
    36→	UE_LOG(LogWjWorldCosmetic, Log, TEXT("CosmeticSubsystem 초기화 완료"));
    37→}
    38→
    39→void UWjWorldCosmeticSubsystem::Deinitialize()
    40→{
    41→	StopInventoryPolling();
    42→	SaveLoadoutToLocal();
    43→
    44→#if WITH_STEAM
    45→	// 대기 중인 결과 핸들 정리
    46→	if (PendingResultHandle != k_SteamInventoryResultInvalid)
    47→	{
    48→		ISteamInventory* SteamInv = SteamInventory();
    49→		if (SteamInv)
    50→		{
    51→			SteamInv->DestroyResult(PendingResultHandle);
    52→		}
    53→		PendingResultHandle = k_SteamInventoryResultInvalid;
    54→	}
    55→#endif
    56→
    57→	Super::Deinitialize();
    58→}
    59→
    60→void UWjWorldCosmeticSubsystem::SetCatalog(UWjWorldCosmeticCatalogDataAsset* InCatalog)
    61→{
    62→	Catalog = InCatalog;
    63→	UE_LOG(LogWjWorldCosmetic, Log, TEXT("카탈로그 설정: %s"), InCatalog ? *InCatalog->GetName() : TEXT("null"));
    64→}
    65→
    66→void UWjWorldCosmeticSubsystem::RequestInventoryRefresh()
    67→{
    68→	if (bInventoryRequestPending)
    69→	{
    70→		UE_LOG(LogWjWorldCosmetic, Log, TEXT("인벤토리 요청이 이미 진행 중입니다."));
    71→		return;
    72→	}
    73→
    74→#if WITH_STEAM
    75→	ISteamInventory* SteamInv = SteamInventory();
    76→	if (!SteamInv)
    77→	{
    78→		UE_LOG(LogWjWorldCosmetic, Warning, TEXT("Steam Inventory API를 사용할 수 없습니다."));
    79→		return;
    80→	}
    81→
    82→	// 기존 핸들 정리
    83→	if (PendingResultHandle != k_SteamInventoryResultInvalid)
    84→	{
    85→		SteamInv->DestroyResult(PendingResultHandle);
    86→		PendingResultHandle = k_SteamInventoryResultInvalid;
    87→	}
    88→
    89→	if (SteamInv->GetAllItems(&PendingResultHandle))
    90→	{
    91→		bInventoryRequestPending = true;
    92→		StartInventoryPolling();
    93→		UE_LOG(LogWjWorldCosmetic, Log, TEXT("Steam 인벤토리 요청 성공 (ResultHandle: %d)"), PendingResultHandle);
    94→	}
    95→	else
    96→	{
    97→		UE_LOG(LogWjWorldCosmetic, Warning, TEXT("Steam 인벤토리 요청 실패"));
    98→	}
    99→#else
   100→	UE_LOG(LogWjWorldCosmetic, Log, TEXT("Steam 미지원 환경 - 인벤토리 갱신 스킵"));
   101→	OnInventoryUpdated.Broadcast();
   102→#endif
   103→}
   104→
   105→bool UWjWorldCosmeticSubsystem::HasItem(FName ItemId) const
   106→{
   107→	return CachedInventory.ContainsByPredicate([ItemId](const FCosmeticItemInstance& Inst)
   108→	{
   109→		return Inst.ItemId == ItemId && Inst.Quantity > 0;
   110→	});
   111→}
   112→
   113→void UWjWorldCosmeticSubsystem::GrantItemLocally(FName ItemId, int32 Quantity)
   114→{
   115→	if (ItemId.IsNone() || Quantity <= 0)
   116→	{
   117→		return;
   118→	}
   119→
   120→	// 기존 아이템 수량 증가 또는 새로 추가
   121→	FCosmeticItemInstance* Existing = CachedInventory.FindByPredicate([ItemId](const FCosmeticItemInstance& Inst)
   122→	{
   123→		return Inst.ItemId == ItemId;
   124→	});
   125→
   126→	if (Existing)
   127→	{
   128→		Existing->Quantity += Quantity;
   129→	}
   130→	else
   131→	{
   132→		FCosmeticItemInstance NewItem(ItemId);
   133→		NewItem.Quantity = Quantity;
   134→		CachedInventory.Add(NewItem);
   135→	}
   136→
   137→	UE_LOG(LogWjWorldCosmetic, Log, TEXT("로컬 아이템 부여: %s x%d"), *ItemId.ToString(), Quantity);
   138→	OnInventoryUpdated.Broadcast();
   139→}
   140→
   141→bool UWjWorldCosmeticSubsystem::EquipItem(ECosmeticSlot Slot, FName ItemId)
   142→{
   143→	if (Slot == ECosmeticSlot::None)
   144→	{
   145→		UE_LOG(LogWjWorldCosmetic, Warning, TEXT("None 슬롯에 장착할 수 없습니다."));
   146→		return false;
   147→	}
   148→
   149→	if (!HasItem(ItemId))
   150→	{
   151→		UE_LOG(LogWjWorldCosmetic, Warning, TEXT("아이템 '%s'을 보유하고 있지 않습니다."), *ItemId.ToString());
   152→		return false;
   153→	}
   154→
   155→	// 카탈로그 검증: 슬롯 일치 확인
   156→	if (Catalog)
   157→	{
   158→		const FCosmeticItemDefinition* Def = Catalog->FindByItemId(ItemId);
   159→		if (Def && Def->Slot != Slot)
   160→		{
   161→			UE_LOG(LogWjWorldCosmetic, Warning, TEXT("아이템 '%s'은 슬롯 %d에 장착할 수 없습니다 (정의된 슬롯: %d)."),
   162→				*ItemId.ToString(), static_cast<int32>(Slot), static_cast<int32>(Def->Slot));
   163→			return false;
   164→		}
   165→	}
   166→
   167→	CurrentLoadout.Equip(Slot, ItemId);
   168→	SaveLoadoutToLocal();
   169→	OnLoadoutChanged.Broadcast(Slot, ItemId);
   170→
   171→	UE_LOG(LogWjWorldCosmetic, Log, TEXT("장착: 슬롯 %d ← %s"), static_cast<int32>(Slot), *ItemId.ToString());
   172→	return true;
   173→}
   174→
   175→void UWjWorldCosmeticSubsystem::UnequipSlot(ECosmeticSlot Slot)
   176→{
   177→	CurrentLoadout.Unequip(Slot);
   178→	SaveLoadoutToLocal();
   179→	OnLoadoutChanged.Broadcast(Slot, NAME_None);
   180→
   181→	UE_LOG(LogWjWorldCosmetic, Log, TEXT("해제: 슬롯 %d"), static_cast<int32>(Slot));
   182→}
   183→
   184→void UWjWorldCosmeticSubsystem::SaveLoadoutToLocal()
   185→{
   186→	for (const FCosmeticSlotEntry& Entry : CurrentLoadout.Entries)
   187→	{
   188→		FString SlotKey = FString::Printf(TEXT("Slot_%d"), static_cast<int32>(Entry.Slot));
   189→		GConfig->SetString(*LoadoutConfigSection, *SlotKey, *Entry.ItemId.ToString(), GGameUserSettingsIni);
   190→	}
   191→
   192→	GConfig->Flush(false, GGameUserSettingsIni);
   193→	UE_LOG(LogWjWorldCosmetic, Log, TEXT("로드아웃 로컬 저장 완료"));
   194→}
   195→
   196→void UWjWorldCosmeticSubsystem::LoadLoadoutFromLocal()
   197→{
   198→	CurrentLoadout.Reset();
   199→
   200→	for (int32 SlotIdx = static_cast<int32>(ECosmeticSlot::Head);
   201→		SlotIdx <= static_cast<int32>(ECosmeticSlot::Effect); ++SlotIdx)
   202→	{
   203→		FString SlotKey = FString::Printf(TEXT("Slot_%d"), SlotIdx);
   204→		FString ItemIdStr;
   205→		if (GConfig->GetString(*LoadoutConfigSection, *SlotKey, ItemIdStr, GGameUserSettingsIni))
   206→		{
   207→			if (!ItemIdStr.IsEmpty())
   208→			{
   209→				CurrentLoadout.Equip(static_cast<ECosmeticSlot>(SlotIdx), FName(*ItemIdStr));
   210→			}
   211→		}
   212→	}
   213→
   214→	UE_LOG(LogWjWorldCosmetic, Log, TEXT("로드아웃 로컬 로드 완료 (%d 슬롯)"), CurrentLoadout.Entries.Num());
   215→}
   216→
   217→void UWjWorldCosmeticSubsystem::StartInventoryPolling()
   218→{
   219→	UWorld* World = GetWorld();
   220→	if (!World)
   221→	{
   222→		return;
   223→	}
   224→
   225→	// 100ms 간격으로 결과 폴링
   226→	World->GetTimerManager().SetTimer(
   227→		InventoryPollTimerHandle,
   228→		this,
   229→		&UWjWorldCosmeticSubsystem::PollSteamInventoryResult,
   230→		0.1f,
   231→		true
   232→	);
   233→
   234→	UE_LOG(LogWjWorldCosmetic, Log, TEXT("인벤토리 폴링 시작"));
   235→}
   236→
   237→void UWjWorldCosmeticSubsystem::StopInventoryPolling()
   238→{
   239→	UWorld* World = GetWorld();
   240→	if (World)
   241→	{
   242→		World->GetTimerManager().ClearTimer(InventoryPollTimerHandle);
   243→	}
   244→	bInventoryRequestPending = false;
   245→
   246→	UE_LOG(LogWjWorldCosmetic, Log, TEXT("인벤토리 폴링 중지"));
   247→}
   248→
   249→void UWjWorldCosmeticSubsystem::PollSteamInventoryResult()
   250→{
   251→#if WITH_STEAM
   252→	if (PendingResultHandle == k_SteamInventoryResultInvalid)
   253→	{
   254→		StopInventoryPolling();
   255→		return;
   256→	}
   257→
   258→	ISteamInventory* SteamInv = SteamInventory();
   259→	if (!SteamInv)
   260→	{
   261→		StopInventoryPolling();
   262→		return;
   263→	}
   264→
   265→	EResult Status = SteamInv->GetResultStatus(PendingResultHandle);
   266→
   267→	if (Status == k_EResultPending)
   268→	{
   269→		// 아직 대기 중 - 계속 폴링
   270→		return;
   271→	}
   272→
   273→	// 결과 처리
   274→	if (Status == k_EResultOK)
   275→	{
   276→		UE_LOG(LogWjWorldCosmetic, Log, TEXT("Steam 인벤토리 결과 수신 성공"));
   277→		ParseInventoryResult();
   278→	}
   279→	else
   280→	{
   281→		UE_LOG(LogWjWorldCosmetic, Warning, TEXT("Steam 인벤토리 결과 실패 (Status: %d)"), static_cast<int32>(Status));
   282→	}
   283→
   284→	// 정리
   285→	SteamInv->DestroyResult(PendingResultHandle);
   286→	PendingResultHandle = k_SteamInventoryResultInvalid;
   287→	StopInventoryPolling();
   288→
   289→	// 델리게이트 브로드캐스트
   290→	OnInventoryUpdated.Broadcast();
   291→#else
   292→	StopInventoryPolling();
   293→#endif
   294→}
   295→
   296→int32 UWjWorldCosmeticSubsystem::GetItemQuantityByDefId(int32 SteamItemDefId) const
   297→{
   298→	const int32* Found = AllItemQuantities.Find(SteamItemDefId);
   299→	return Found ? *Found : 0;
   300→}
   301→
   302→void UWjWorldCosmeticSubsystem::ParseInventoryResult()
   303→{
   304→#if WITH_STEAM
   305→	ISteamInventory* SteamInv = SteamInventory();
   306→	if (!SteamInv)
   307→	{
   308→		UE_LOG(LogWjWorldCosmetic, Warning, TEXT("ParseInventoryResult: SteamInventory 없음"));
   309→		return;
   310→	}
   311→
   312→	if (PendingResultHandle == k_SteamInventoryResultInvalid)
   313→	{
   314→		return;
   315→	}
   316→
   317→	// 아이템 개수 확인
   318→	uint32 ItemCount = 0;
   319→	if (!SteamInv->GetResultItems(PendingResultHandle, nullptr, &ItemCount) || ItemCount == 0)
   320→	{
   321→		UE_LOG(LogWjWorldCosmetic, Log, TEXT("Steam 인벤토리: 아이템 0개"));
   322→		CachedInventory.Empty();
   323→		AllItemQuantities.Empty();
   324→		return;
   325→	}
   326→
   327→	// 아이템 상세 정보 가져오기
   328→	TArray<SteamItemDetails_t> ItemDetails;
   329→	ItemDetails.SetNum(ItemCount);
   330→
   331→	if (!SteamInv->GetResultItems(PendingResultHandle, ItemDetails.GetData(), &ItemCount))
   332→	{
   333→		UE_LOG(LogWjWorldCosmetic, Warning, TEXT("Steam 인벤토리 아이템 상세 정보 가져오기 실패"));
   334→		return;
   335→	}
   336→
   337→	// 전체 DefId별 수량 캐시 갱신 (배치 오브젝트 소유권 추적용)
   338→	AllItemQuantities.Empty();
   339→	for (uint32 i = 0; i < ItemCount; ++i)
   340→	{
   341→		const SteamItemDetails_t& Details = ItemDetails[i];
   342→		if (Details.m_unQuantity > 0)
   343→		{
   344→			AllItemQuantities.FindOrAdd(Details.m_iDefinition) += Details.m_unQuantity;
   345→		}
   346→	}
   347→
   348→	// 캐시된 코스메틱 인벤토리 갱신 (Catalog 필요)
   349→	CachedInventory.Empty(ItemCount);
   350→
   351→	if (!Catalog)
   352→	{
   353→		UE_LOG(LogWjWorldCosmetic, Warning, TEXT("ParseInventoryResult: Catalog 없음 — 전체 수량만 캐싱"));
   354→		return;
   355→	}
   356→
   357→	for (uint32 i = 0; i < ItemCount; ++i)
   358→	{
   359→		const SteamItemDetails_t& Details = ItemDetails[i];
   360→
   361→		// 수량 체크 (0이면 소비됨/만료됨)
   362→		if (Details.m_unQuantity == 0)
   363→		{
   364→			continue;
   365→		}
   366→
   367→		// SteamItemDefId → ItemId 변환
   368→		FName ItemId = Catalog->SteamItemDefIdToItemId(Details.m_iDefinition);
   369→		if (ItemId.IsNone())
   370→		{
   371→			// 코스메틱 카탈로그에 없는 아이템 — 전체 수량 캐시에는 이미 기록됨
   372→			continue;
   373→		}
   374→
   375→		// 기존 아이템 수량 증가 또는 새로 추가
   376→		FCosmeticItemInstance* Existing = CachedInventory.FindByPredicate([ItemId](const FCosmeticItemInstance& Inst)
   377→		{
   378→			return Inst.ItemId == ItemId;
   379→		});
   380→
   381→		if (Existing)
   382→		{
   383→			Existing->Quantity += Details.m_unQuantity;
   384→		}
   385→		else
   386→		{
   387→			FCosmeticItemInstance NewItem(ItemId);
   388→			NewItem.Quantity = Details.m_unQuantity;
   389→			CachedInventory.Add(NewItem);
   390→		}
   391→
   392→		UE_LOG(LogWjWorldCosmetic, Verbose, TEXT("인벤토리 아이템: %s (DefId: %d, Qty: %d)"),
   393→			*ItemId.ToString(), Details.m_iDefinition, Details.m_unQuantity);
   394→	}
   395→
   396→	UE_LOG(LogWjWorldCosmetic, Log, TEXT("Steam 인벤토리 파싱 완료: %d개 코스메틱 아이템, %d개 전체 DefId"),
   397→		CachedInventory.Num(), AllItemQuantities.Num());
   398→#endif
   399→}
