   401→void UWjWorldCosmeticSubsystem::LoadPlacementInventoryFromLocal()
   402→{
   403→#if !WITH_STEAM
   404→	// 비Steam 환경: GConfig에서 배치 오브젝트 소유 수량 로드
   405→	static const FString PlacementInventorySection = TEXT("PlacementInventory");
   406→
   407→	TArray<FString> Keys;
   408→	GConfig->GetSection(*PlacementInventorySection, Keys, GGameUserSettingsIni);
   409→
   410→	for (const FString& KeyValuePair : Keys)
   411→	{
   412→		FString Key, Value;
   413→		if (KeyValuePair.Split(TEXT("="), &Key, &Value))
   414→		{
   415→			int32 Quantity = FCString::Atoi(*Value);
   416→			if (Quantity > 0)
   417→			{
   418→				// ObjectId에 해당하는 SteamItemDefId를 찾아서 AllItemQuantities에 기록
   419→				// DeveloperSettings의 카탈로그에서 검색
   420→				const UWjWorldDeveloperSettings* Settings = GetDefault<UWjWorldDeveloperSettings>();
   421→				if (Settings)
   422→				{
   423→					UWjWorldPlaceableObjectDataAsset* PlacementCatalog = Settings->GetPlaceableCatalogForContext(EPlacementContext::Lobby);
   424→					if (PlacementCatalog)
   425→					{
   426→						const FPlaceableObjectDefinition* Def = PlacementCatalog->FindByObjectId(FName(*Key));
   427→						if (Def && Def->SteamItemDefId > 0)
   428→						{
   429→							AllItemQuantities.FindOrAdd(Def->SteamItemDefId) += Quantity;
   430→						}
   431→					}
   432→				}
   433→			}
   434→		}
   435→	}
   436→
   437→	UE_LOG(LogWjWorldCosmetic, Log, TEXT("비Steam 배치 인벤토리 로드 완료 (%d DefIds)"), AllItemQuantities.Num());
   438→#endif
   439→}
