   689→void UWjWorldCurrencySubsystem::PollExchangeResult()
   690→{
   691→#if WITH_STEAM
   692→	if (!bExchangePending || ExchangeResultHandle == k_SteamInventoryResultInvalid)
   693→	{
   694→		StopExchangePolling();
   695→		return;
   696→	}
   697→
   698→	ISteamInventory* SteamInv = SteamInventory();
   699→	if (!SteamInv)
   700→	{
   701→		StopExchangePolling();
   702→		bExchangePending = false;
   703→		if (bPendingIsPlacement)
   704→		{
   705→			OnPlacementPurchaseComplete.Broadcast(PendingExchangeItemId, false);
   706→		}
   707→		else
   708→		{
   709→			OnCurrencyPurchaseComplete.Broadcast(PendingExchangeItemId, false);
   710→		}
   711→		bPendingIsPlacement = false;
   712→		PendingExchangeItemId = NAME_None;
   713→		return;
   714→	}
   715→
   716→	EResult Status = SteamInv->GetResultStatus(ExchangeResultHandle);
   717→	if (Status == k_EResultPending)
   718→	{
   719→		return;
   720→	}
   721→
   722→	bool bSuccess = (Status == k_EResultOK);
   723→	if (bSuccess)
   724→	{
   725→		UE_LOG(LogWjWorldCurrency, Log, TEXT("Steam Exchange 성공: %s"), *PendingExchangeItemId.ToString());
   726→
   727→		// 인벤토리 갱신
   728→		UWjWorldCosmeticSubsystem* CosmeticSub = GetGameInstance()->GetSubsystem<UWjWorldCosmeticSubsystem>();
   729→		if (CosmeticSub)
   730→		{
   731→			CosmeticSub->RequestInventoryRefresh();
   732→		}
   733→	}
   734→	else
   735→	{
   736→		UE_LOG(LogWjWorldCurrency, Warning, TEXT("Steam Exchange 실패: %s (Status: %d)"),
   737→			*PendingExchangeItemId.ToString(), static_cast<int32>(Status));
   738→	}
   739→
   740→	SteamInv->DestroyResult(ExchangeResultHandle);
   741→	ExchangeResultHandle = k_SteamInventoryResultInvalid;
   742→
   743→	bExchangePending = false;
   744→
   745→	// 배치 vs 코스메틱 분기
   746→	if (bPendingIsPlacement)
   747→	{
   748→		OnPlacementPurchaseComplete.Broadcast(PendingExchangeItemId, bSuccess);
   749→	}
   750→	else
   751→	{
   752→		OnCurrencyPurchaseComplete.Broadcast(PendingExchangeItemId, bSuccess);
   753→	}
   754→	bPendingIsPlacement = false;
   755→	PendingExchangeItemId = NAME_None;
   756→
   757→	StopExchangePolling();
   758→#else
   759→	StopExchangePolling();
   760→#endif
   761→}
