   763→void UWjWorldCurrencySubsystem::StartExchangePolling()
   764→{
   765→	UWorld* World = GetWorld();
   766→	if (!World)
   767→	{
   768→		return;
   769→	}
   770→
   771→	World->GetTimerManager().SetTimer(
   772→		ExchangePollTimerHandle,
   773→		this,
   774→		&UWjWorldCurrencySubsystem::PollExchangeResult,
   775→		0.5f,
   776→		true
   777→	);
   778→}
