   789→void UWjWorldCurrencySubsystem::PollGemPurchaseResult()
   790→{
   791→#if WITH_STEAM
   792→	if (!bGemPurchasePending)
   793→	{
   794→		StopGemPurchasePolling();
   795→		return;
   796→	}
   797→
   798→	// Gem 팩 구매는 Steam 오버레이를 통해 처리되므로
   799→	// 인벤토리 변경을 감지하여 완료 판단
   800→	// CosmeticSubsystem의 OnInventoryUpdated → HandleInventoryUpdated → RefreshBalancesFromInventory
   801→	// 에서 Gem 잔액 변경이 감지되면 구매 완료로 판단
   802→
   803→	// 간단한 타임아웃 처리 (300초)
   804→	UWorld* World = GetWorld();
   805→	if (World)
   806→	{
   807→		if (GemPurchaseStartTime == 0.0f)
   808→		{
   809→			GemPurchaseStartTime = World->GetTimeSeconds();
   810→		}
   811→
   812→		float ElapsedTime = World->GetTimeSeconds() - GemPurchaseStartTime;
   813→		if (ElapsedTime > 300.0f)
   814→		{
   815→			UE_LOG(LogWjWorldCurrency, Warning, TEXT("Gem 팩 구매 타임아웃"));
   816→			bGemPurchasePending = false;
   817→			GemPurchaseStartTime = 0.0f;
   818→			StopGemPurchasePolling();
   819→		}
   820→	}
   821→#else
   822→	StopGemPurchasePolling();
   823→#endif
   824→}
   825→
   826→void UWjWorldCurrencySubsystem::StartGemPurchasePolling()
   827→{
   828→	UWorld* World = GetWorld();
   829→	if (!World)
   830→	{
   831→		return;
   832→	}
   833→
   834→	World->GetTimerManager().SetTimer(
   835→		GemPurchasePollTimerHandle,
   836→		this,
   837→		&UWjWorldCurrencySubsystem::PollGemPurchaseResult,
   838→		1.0f,
   839→		true
   840→	);
