   861→void UWjWorldCurrencySubsystem::LoadBalancesFromLocal()
   862→{
   863→	int32 LoadedCoin = 0;
   864→	int32 LoadedGem = 0;
   865→
   866→	GConfig->GetInt(*CurrencyConfigSection, TEXT("CoinBalance"), LoadedCoin, GGameUserSettingsIni);
   867→	GConfig->GetInt(*CurrencyConfigSection, TEXT("GemBalance"), LoadedGem, GGameUserSettingsIni);
   868→
   869→	CoinBalance = FMath::Max(0, LoadedCoin);
   870→	GemBalance = FMath::Max(0, LoadedGem);
   871→
   872→	UE_LOG(LogWjWorldCurrency, Log, TEXT("재화 잔액 로컬 로드 완료 (Coin: %d, Gem: %d)"), CoinBalance, GemBalance);
   873→}
