   875→void UWjWorldCurrencySubsystem::SetBalance(ECurrencyType Type, int32 NewAmount)
   876→{
   877→	NewAmount = FMath::Max(0, NewAmount);
   878→
   879→	switch (Type)
   880→	{
   881→	case ECurrencyType::Coin:
   882→		if (CoinBalance != NewAmount)
   883→		{
   884→			CoinBalance = NewAmount;
   885→			OnCurrencyBalanceChanged.Broadcast(ECurrencyType::Coin, CoinBalance);
   886→		}
   887→		break;
   888→	case ECurrencyType::Gem:
   889→		if (GemBalance != NewAmount)
   890→		{
   891→			GemBalance = NewAmount;
   892→			OnCurrencyBalanceChanged.Broadcast(ECurrencyType::Gem, GemBalance);
   893→		}
   894→		break;
   895→	}
   896→}
