   401→void UPlacementHUDWidgetBase::UpdateTotalPlacementCountText()
   402→{
   403→	if (!TotalPlacementCountText || !PlacementComponent)
   404→	{
   405→		return;
   406→	}
   407→
   408→	if (GetCurrentContext() != EPlacementContext::Lobby)
   409→	{
   410→		TotalPlacementCountText->SetVisibility(ESlateVisibility::Collapsed);
   411→		return;
   412→	}
   413→
   414→	const UWjWorldDeveloperSettings* Settings = GetDefault<UWjWorldDeveloperSettings>();
   415→	IWjWorldPlacementDataProvider* DataProvider = PlacementComponent->GetPlacementDataProvider();
   416→	if (!Settings || !DataProvider)
   417→	{
   418→		return;
   419→	}
   420→
   421→	int32 CurrentCount = DataProvider->GetPlacedObjects().Num();
   422→	int32 MaxCount = Settings->MaxTotalLobbyPlacedObjects;
   423→
   424→	if (MaxCount > 0)
   425→	{
   426→		TotalPlacementCountText->SetText(FText::FromString(FString::Printf(TEXT("%d/%d"), CurrentCount, MaxCount)));
   427→		TotalPlacementCountText->SetVisibility(ESlateVisibility::Visible);
   428→	}
   429→	else
   430→	{
   431→		TotalPlacementCountText->SetText(FText::FromString(FString::Printf(TEXT("%d"), CurrentCount)));
   432→		TotalPlacementCountText->SetVisibility(ESlateVisibility::Visible);
   433→	}
   434→}
