    45→void UPlacementHUDWidgetBase::SetPlacementComponent(UWjWorldPlacementComponent* InComponent)
    46→{
    47→	PlacementComponent = InComponent;
    48→
    49→	if (PlacementComponent)
    50→	{
    51→		PopulateCatalog(PlacementComponent->GetCatalog());
    52→
    53→		// 배치/삭제 시 카탈로그 리프레시 (배치 수 갱신)
    54→		PlacementComponent->OnObjectPlaced.AddDynamic(this, &UPlacementHUDWidgetBase::RefreshCatalogUI);
    55→		PlacementComponent->OnObjectDeleted.AddDynamic(this, &UPlacementHUDWidgetBase::RefreshCatalogUI);
    56→
    57→		// 로비 컨텍스트: 구매/인벤토리 델리게이트 구독
    58→		if (GetCurrentContext() == EPlacementContext::Lobby)
    59→		{
    60→			UGameInstance* GI = GetGameInstance();
    61→			if (GI)
    62→			{
    63→				UWjWorldCurrencySubsystem* CurrencySub = GI->GetSubsystem<UWjWorldCurrencySubsystem>();
    64→				if (CurrencySub)
    65→				{
    66→					CurrencySub->OnPlacementPurchaseComplete.AddDynamic(this, &UPlacementHUDWidgetBase::HandlePlacementPurchaseComplete);
    67→				}
    68→
    69→				UWjWorldCosmeticSubsystem* CosmeticSub = GI->GetSubsystem<UWjWorldCosmeticSubsystem>();
    70→				if (CosmeticSub)
    71→				{
    72→					CosmeticSub->OnInventoryUpdated.AddDynamic(this, &UPlacementHUDWidgetBase::HandleInventoryUpdated);
    73→				}
    74→			}
    75→		}
    76→	}
    77→}
