    87→
    88→void UPlacementHUDWidgetBase::PopulateCatalog(UWjWorldPlaceableObjectDataAsset* Catalog)
    89→{
    90→	if (!CatalogScrollBox || !Catalog)
    91→	{
    92→		return;
    93→	}
    94→
    95→	CatalogScrollBox->ClearChildren();
    96→	ButtonToObjectIdMap.Empty();
    97→
    98→	// 로비 컨텍스트일 때만 소유권/가격 정보 표시
    99→	bool bIsLobby = (GetCurrentContext() == EPlacementContext::Lobby);
   100→	UWjWorldCosmeticSubsystem* CosmeticSub = nullptr;
   101→	int32 CoinBalance = 0;
   102→
   103→	if (bIsLobby)
   104→	{
   105→		UGameInstance* GI = GetGameInstance();
   106→		if (GI)
   107→		{
   108→			CosmeticSub = GI->GetSubsystem<UWjWorldCosmeticSubsystem>();
   109→			UWjWorldCurrencySubsystem* CurrencySub = GI->GetSubsystem<UWjWorldCurrencySubsystem>();
   110→			if (CurrencySub)
   111→			{
   112→				CoinBalance = CurrencySub->GetBalance(ECurrencyType::Coin);
   113→			}
   114→		}
   115→	}
   116→
   117→	for (const FPlaceableObjectDefinition& Def : Catalog->Objects)
   118→	{
   119→		UButton* ItemButton = NewObject<UButton>(this);
   120→		UTextBlock* ItemText = NewObject<UTextBlock>(this);
   121→
   122→		// 표시 텍스트 구성
   123→		FString DisplayStr = Def.DisplayName.IsEmpty() ? Def.ObjectId.ToString() : Def.DisplayName.ToString();
   124→
   125→		if (bIsLobby && Def.CoinPrice > 0 && Def.SteamItemDefId > 0)
   126→		{
   127→			int32 OwnedQty = CosmeticSub ? CosmeticSub->GetItemQuantityByDefId(Def.SteamItemDefId) : 0;
   128→
   129→			if (OwnedQty > 0)
   130→			{
   131→				// 소유 중: 배치 수 표시
   132→				if (Def.MaxPlacementCount > 0 && PlacementComponent)
   133→				{
   134→					int32 PlacedCount = PlacementComponent->CountPlacedObjectsByType(Def.ObjectId);
   135→					DisplayStr += FString::Printf(TEXT("  [%d/%d]"), PlacedCount, Def.MaxPlacementCount);
   136→				}
   137→			}
   138→			else
   139→			{
   140→				// 미소유: 가격 표시
   141→				DisplayStr += FString::Printf(TEXT("  (%d Coin)"), Def.CoinPrice);
   142→			}
   143→		}
   144→		else if (bIsLobby && Def.MaxPlacementCount > 0 && PlacementComponent)
   145→		{
   146→			// 무료이지만 배치 상한이 있는 경우
   147→			int32 PlacedCount = PlacementComponent->CountPlacedObjectsByType(Def.ObjectId);
   148→			DisplayStr += FString::Printf(TEXT("  [%d/%d]"), PlacedCount, Def.MaxPlacementCount);
   149→		}
   150→
   151→		ItemText->SetText(FText::FromString(DisplayStr));
   152→
   153→		// 버튼 스타일링
   154→		FSlateFontInfo FontInfo = ItemText->GetFont();
   155→		FontInfo.Size = 14;
   156→		ItemText->SetFont(FontInfo);
   157→
   158→		// 잔액 부족 미소유 아이템: 색상 변경
   159→		if (bIsLobby && Def.CoinPrice > 0 && Def.SteamItemDefId > 0)
   160→		{
   161→			int32 OwnedQty = CosmeticSub ? CosmeticSub->GetItemQuantityByDefId(Def.SteamItemDefId) : 0;
   162→			if (OwnedQty <= 0 && CoinBalance < Def.CoinPrice)
   163→			{
   164→				ItemText->SetColorAndOpacity(FSlateColor(FLinearColor(0.5f, 0.5f, 0.5f)));
   165→			}
   166→			else if (OwnedQty <= 0)
   167→			{
   168→				ItemText->SetColorAndOpacity(FSlateColor(FLinearColor(1.0f, 0.8f, 0.2f)));
   169→			}
   170→		}
   171→
   172→		ItemButton->AddChild(ItemText);
   173→
   174→		// 버튼 → ObjectId 매핑 등록 + 공통 핸들러 바인딩
   175→		ButtonToObjectIdMap.Add(ItemButton, Def.ObjectId);
   176→		ItemButton->OnClicked.AddDynamic(this, &UPlacementHUDWidgetBase::OnCatalogButtonClicked);
   177→
   178→		CatalogScrollBox->AddChild(ItemButton);
   179→	}
   180→
   181→	UpdateTotalPlacementCountText();
   182→
   183→	UE_LOG(LogWjWorldPlacement, Log, TEXT("PlacementHUDWidgetBase: Catalog populated with %d items"), Catalog->Objects.Num());
   184→}
