   200→void UPlacementHUDWidgetBase::OnSaveClicked()
   201→{
   202→	UE_LOG(LogWjWorldPlacement, Log, TEXT("PlacementHUDWidgetBase: Save clicked"));
   203→
   204→	if (!SaveDialogClass)
   205→	{
   206→		// 다이얼로그 클래스가 없으면 기본 슬롯 이름으로 바로 저장
   207→		FString DefaultSlotName = GetCurrentLoadedSlotName();
   208→		if (DefaultSlotName.IsEmpty())
   209→		{
   210→			DefaultSlotName = GetSaveSlotNameForContext(GetCurrentContext());
   211→		}
   212→		ExecuteSave(DefaultSlotName);
   213→		return;
   214→	}
   215→
   216→	// 이미 열려있으면 스킵
   217→	if (SaveDialogInstance && SaveDialogInstance->IsInViewport())
   218→	{
   219→		return;
   220→	}
   221→
   222→	// 다이얼로그 생성
   223→	SaveDialogInstance = CreateWidget<UPlacementSaveDialogWidget>(GetOwningPlayer(), SaveDialogClass);
   224→	if (SaveDialogInstance)
   225→	{
   226→		// 로드된 슬롯 이름이 있으면 그것을 기본값으로, 없으면 컨텍스트 기본값 사용
   227→		FString DefaultSlotName = GetCurrentLoadedSlotName();
   228→		if (DefaultSlotName.IsEmpty())
   229→		{
   230→			DefaultSlotName = GetSaveSlotNameForContext(GetCurrentContext());
   231→		}
   232→		SaveDialogInstance->SetDefaultSlotName(DefaultSlotName);
   233→		SaveDialogInstance->SetContext(GetCurrentContext());
   234→
   235→		// 콜백 바인딩
   236→		SaveDialogInstance->OnSaveConfirmed.AddDynamic(this, &UPlacementHUDWidgetBase::OnSaveConfirmed);
   237→		SaveDialogInstance->ShowPopup();
   238→	}
   239→}
   240→
   241→void UPlacementHUDWidgetBase::OnSaveConfirmed(const FString& SlotName)
   242→{
   243→	UE_LOG(LogWjWorldPlacement, Log, TEXT("PlacementHUDWidgetBase: Save confirmed with slot name: %s"), *SlotName);
   244→	ExecuteSave(SlotName);
   245→}
   246→
   247→void UPlacementHUDWidgetBase::ExecuteSave(const FString& SlotName)
   248→{
   249→	// 기본 구현: PlacementComponent의 SaveLayoutToSlot 호출
   250→	if (PlacementComponent)
   251→	{
   252→		PlacementComponent->SaveLayoutToSlot(SlotName);
   253→		UE_LOG(LogWjWorldPlacement, Log, TEXT("PlacementHUDWidgetBase: Layout saved to slot '%s'"), *SlotName);
   254→	}
   255→}
   256→
   257→void UPlacementHUDWidgetBase::OnCatalogButtonClicked()
   258→{
   259→	// 호버 상태인 버튼을 찾아 ObjectId 매핑 조회
   260→	for (const auto& Pair : ButtonToObjectIdMap)
   261→	{
   262→		if (Pair.Key && Pair.Key->IsHovered())
   263→		{
   264→			OnCatalogItemClicked(Pair.Value);
   265→			return;
   266→		}
   267→	}
   268→}
   269→
   270→void UPlacementHUDWidgetBase::OnCatalogItemClicked(FName ObjectId)
   271→{
   272→	if (!PlacementComponent)
   273→	{
   274→		return;
   275→	}
   276→
   277→	// 로비 컨텍스트: 미소유 유료 아이템 클릭 시 구매 시도
   278→	if (GetCurrentContext() == EPlacementContext::Lobby)
   279→	{
   280→		UWjWorldPlaceableObjectDataAsset* Catalog = PlacementComponent->GetCatalog();
   281→		if (Catalog)
   282→		{
   283→			const FPlaceableObjectDefinition* Def = Catalog->FindByObjectId(ObjectId);
   284→			if (Def && Def->CoinPrice > 0 && Def->SteamItemDefId > 0)
   285→			{
   286→				UGameInstance* GI = GetGameInstance();
   287→				UWjWorldCosmeticSubsystem* CosmeticSub = GI ? GI->GetSubsystem<UWjWorldCosmeticSubsystem>() : nullptr;
   288→				int32 OwnedQty = CosmeticSub ? CosmeticSub->GetItemQuantityByDefId(Def->SteamItemDefId) : 0;
   289→
   290→				if (OwnedQty <= 0)
   291→				{
   292→					// 미소유 → 구매 시도
   293→					UWjWorldCurrencySubsystem* CurrencySub = GI ? GI->GetSubsystem<UWjWorldCurrencySubsystem>() : nullptr;
   294→					if (CurrencySub)
   295→					{
   296→						CurrencySub->PurchasePlacementObject(ObjectId);
   297→						UE_LOG(LogWjWorldPlacement, Log, TEXT("PlacementHUDWidgetBase: 구매 시도 %s"), *ObjectId.ToString());
   298→					}
   299→					return;
   300→				}
   301→			}
   302→		}
   303→	}
   304→
   305→	PlacementComponent->SelectObject(ObjectId);
   306→	UE_LOG(LogWjWorldPlacement, Log, TEXT("PlacementHUDWidgetBase: Selected object %s"), *ObjectId.ToString());
   307→}
