   207→void UWjWorldPlacementComponent::ConfirmPlacement()
   208→{
   209→	if (CurrentMode != EPlacementMode::Placing || !PreviewActor || !bCurrentPreviewValid)
   210→	{
   211→		return;
   212→	}
   213→
   214→	if (!Catalog)
   215→	{
   216→		return;
   217→	}
   218→
   219→	const FPlaceableObjectDefinition* Def = Catalog->FindByObjectId(SelectedObjectId);
   220→	if (!Def)
   221→	{
   222→		return;
   223→	}
   224→
   225→	IWjWorldPlacementDataProvider* DataProvider = GetPlacementDataProvider();
   226→	if (!DataProvider)
   227→	{
   228→		UE_LOG(LogWjWorldPlacement, Warning, TEXT("PlacementComponent: PlacementDataProvider not found"));
   229→		return;
   230→	}
   231→
   232→	// 로비 컨텍스트: 배치 수량 제한 체크
   233→	if (CurrentContext == EPlacementContext::Lobby)
   234→	{
   235→		const UWjWorldDeveloperSettings* DevSettings = GetDefault<UWjWorldDeveloperSettings>();
   236→
   237→		// 전체 배치 상한
   238→		if (DevSettings && DevSettings->MaxTotalLobbyPlacedObjects > 0)
   239→		{
   240→			if (DataProvider->GetPlacedObjects().Num() >= DevSettings->MaxTotalLobbyPlacedObjects)
   241→			{
   242→				UE_LOG(LogWjWorldPlacement, Warning, TEXT("PlacementComponent: 전체 배치 상한 도달 (%d/%d)"),
   243→					DataProvider->GetPlacedObjects().Num(), DevSettings->MaxTotalLobbyPlacedObjects);
   244→				return;
   245→			}
   246→		}
   247→
   248→		// 종류당 배치 상한
   249→		if (Def->MaxPlacementCount > 0)
   250→		{
   251→			int32 CurrentTypeCount = CountPlacedObjectsByType(SelectedObjectId);
   252→			if (CurrentTypeCount >= Def->MaxPlacementCount)
   253→			{
   254→				UE_LOG(LogWjWorldPlacement, Warning, TEXT("PlacementComponent: 종류당 배치 상한 도달 (%s: %d/%d)"),
   255→					*SelectedObjectId.ToString(), CurrentTypeCount, Def->MaxPlacementCount);
   256→				return;
   257→			}
   258→		}
   259→	}
   260→
   261→	// 배치 데이터 생성
   262→	FVector SpawnLocation = PreviewActor->GetActorLocation();
   263→	FRotator SpawnRotation = PreviewActor->GetCurrentRotation();
   264→
   265→	FPlacedObjectSaveEntry Entry;
   266→	Entry.ObjectId = SelectedObjectId;
   267→	Entry.Transform = FTransform(SpawnRotation, SpawnLocation, Def->DefaultScale);
   268→
   269→	// JumpMap 컨텍스트: Checkpoint 오브젝트에 자동 CheckpointOrder 할당
   270→	if (CurrentContext == EPlacementContext::JumpMap)
   271→	{
   272→		FString ObjectIdStr = SelectedObjectId.ToString();
   273→		if (ObjectIdStr.Contains(TEXT("Checkpoint")))
   274→		{
   275→			int32 MaxOrder = -1;
   276→			const TArray<FPlacedObjectSaveEntry>& Existing = DataProvider->GetPlacedObjects();
   277→			for (const FPlacedObjectSaveEntry& Obj : Existing)
   278→			{
   279→				if (Obj.ObjectId.ToString().Contains(TEXT("Checkpoint")))
   280→				{
   281→					const FString* OrderStr = Obj.CustomProperties.Find(TEXT("CheckpointOrder"));
   282→					if (OrderStr)
   283→					{
   284→						MaxOrder = FMath::Max(MaxOrder, FCString::Atoi(**OrderStr));
   285→					}
   286→				}
   287→			}
   288→			Entry.CustomProperties.Add(TEXT("CheckpointOrder"), FString::FromInt(MaxOrder + 1));
   289→		}
   290→	}
   291→
   292→	// DataProvider에 추가 (서버에서 스폰 + 클라이언트 리플리케이션)
   293→	DataProvider->AddPlacedObject(Entry);
   294→
   295→	// 새로 생성된 액터에도 배치 모드 비주얼 적용
   296→	RefreshPlacementModeVisuals();
   297→
   298→	// 로컬 SaveGame에도 저장 (호스트 영구 저장용)
   299→	SaveLayout();
   300→
   301→	OnObjectPlaced.Broadcast();
   302→	UE_LOG(LogWjWorldPlacement, Log, TEXT("PlacementComponent: Object placed - ObjectId=%s at %s (Context: %s)"),
   303→		*SelectedObjectId.ToString(), *SpawnLocation.ToString(), *GetPlacementContextName(CurrentContext));
   304→}
   305→
   306→void UWjWorldPlacementComponent::DeleteHoveredObject()
   307→{
   308→	if (CurrentMode != EPlacementMode::Deleting || !HoveredObject)
   309→	{
   310→		return;
   311→	}
   312→
   313→	IWjWorldPlacementDataProvider* DataProvider = GetPlacementDataProvider();
   314→	if (!DataProvider)
   315→	{
   316→		UE_LOG(LogWjWorldPlacement, Warning, TEXT("PlacementComponent: PlacementDataProvider not found"));
   317→		return;
   318→	}
   319→
   320→	// DataProvider에서 해당 오브젝트 인덱스 찾기
   321→	int32 Index = FindPlacedObjectIndex(HoveredObject);
   322→	if (Index == INDEX_NONE)
   323→	{
   324→		UE_LOG(LogWjWorldPlacement, Warning, TEXT("PlacementComponent: Could not find object index for deletion"));
   325→		return;
   326→	}
   327→
   328→	HoveredObject = nullptr;
   329→
   330→	// DataProvider에서 제거 (서버에서 파괴 + 클라이언트 리플리케이션)
   331→	DataProvider->RemovePlacedObjectAt(Index);
   332→
   333→	// 로컬 SaveGame에도 저장
   334→	SaveLayout();
   335→
   336→	OnObjectDeleted.Broadcast();
   337→	UE_LOG(LogWjWorldPlacement, Log, TEXT("PlacementComponent: Object deleted at index %d"), Index);
   338→}
