   345→void UWjWorldPlacementComponent::SaveLayout()
   346→{
   347→	// 호스트(ListenServer 또는 Standalone)인 경우에만 SaveGame 저장
   348→	// 클라이언트가 저장하면 다른 세션의 배치물이 섞이는 문제 발생
   349→	UWorld* World = GetWorld();
   350→	if (!World)
   351→	{
   352→		return;
   353→	}
   354→
   355→	ENetMode NetMode = World->GetNetMode();
   356→	if (NetMode != NM_Standalone && NetMode != NM_ListenServer)
   357→	{
   358→		UE_LOG(LogWjWorldPlacement, Log, TEXT("PlacementComponent: SaveLayout skipped (not host)"));
   359→		return;
   360→	}
   361→
   362→	// DataProvider에서 데이터를 가져와 로컬 SaveGame에 저장 (호스트 영구 저장용)
