   409→	}
   410→
   411→	ENetMode NetMode = World->GetNetMode();
   412→	if (NetMode != NM_Standalone && NetMode != NM_ListenServer)
   413→	{
   414→		UE_LOG(LogWjWorldPlacement, Log, TEXT("PlacementComponent: SaveLayoutToSlot skipped (not host)"));
   415→		return;
   416→	}
   417→
   418→	IWjWorldPlacementDataProvider* DataProvider = GetPlacementDataProvider();
   419→	if (!DataProvider)
   420→	{
   421→		return;
   422→	}
   423→
   424→	UWjWorldLayoutSaveGame* SaveGame = Cast<UWjWorldLayoutSaveGame>(
   425→		UGameplayStatics::CreateSaveGameObject(UWjWorldLayoutSaveGame::StaticClass())
   426→	);
   427→
   428→	if (!SaveGame)
   429→	{
   430→		UE_LOG(LogWjWorldPlacement, Error, TEXT("PlacementComponent: Failed to create save game object"));
   431→		return;
   432→	}
   433→
   434→	// DataProvider의 배치 데이터 복사
   435→	SaveGame->PlacedObjects = DataProvider->GetPlacedObjects();
   436→	SaveGame->SavedContext = CurrentContext;
