   448→		}
   449→		// JumpMap 컨텍스트인 경우 CSV도 함께 내보내기
   450→		else if (CurrentContext == EPlacementContext::JumpMap)
   451→		{
   452→			ExportJumpMapLayoutAsCSV(SlotName);
   453→		}
   454→	}
   455→	else
   456→	{
   457→		UE_LOG(LogWjWorldPlacement, Error, TEXT("PlacementComponent: Failed to save layout to '%s'"), *SlotName);
