   461→bool UWjWorldPlacementComponent::LoadLayoutFromSlot(const FString& SlotName)
   462→{
   463→	UWorld* World = GetWorld();
   464→	if (!World)
   465→	{
   466→		return false;
   467→	}
   468→
   469→	// SaveGame 로드
   470→	UWjWorldLayoutSaveGame* SaveGame = Cast<UWjWorldLayoutSaveGame>(
   471→		UGameplayStatics::LoadGameFromSlot(SlotName, 0)
   472→	);
   473→
   474→	if (!SaveGame)
   475→	{
   476→		UE_LOG(LogWjWorldPlacement, Warning, TEXT("PlacementComponent: Failed to load layout from '%s'"), *SlotName);
   477→		return false;
   478→	}
   479→
   480→	// 컨텍스트 검증 (다른 컨텍스트의 레이아웃 로드 방지)
   481→	if (SaveGame->SavedContext != EPlacementContext::None && SaveGame->SavedContext != CurrentContext)
   482→	{
   483→		UE_LOG(LogWjWorldPlacement, Warning, TEXT("PlacementComponent: Context mismatch - slot '%s' is for '%s', current context is '%s'"),
   484→			*SlotName, *GetPlacementContextName(SaveGame->SavedContext), *GetPlacementContextName(CurrentContext));
   485→		return false;
   486→	}
   487→
   488→	// DataProvider가 있으면 데이터 설정
   489→	IWjWorldPlacementDataProvider* DataProvider = GetPlacementDataProvider();
   490→	if (DataProvider)
   491→	{
   492→		// 일괄 설정 (RespawnAllPlacedObjects가 한 번만 호출됨)
   493→		DataProvider->SetPlacedObjects(SaveGame->PlacedObjects);
   494→	}
   495→
   496→	LoadedSlotName = SlotName;
   497→
   498→	// 로드된 오브젝트에 배치 모드 비주얼 적용
   499→	RefreshPlacementModeVisuals();
   500→
   501→	UE_LOG(LogWjWorldPlacement, Log, TEXT("PlacementComponent: Layout loaded from '%s' (%d objects)"),
   502→		*SlotName, SaveGame->PlacedObjects.Num());
   503→	return true;
   504→}
