   506→TArray<FString> UWjWorldPlacementComponent::GetSavedLayoutSlots() const
   507→{
   508→	TArray<FString> SlotNames;
   509→
   510→	// SaveGame 디렉토리에서 모든 .sav 파일 검색
   511→	FString SaveDirectory = FPaths::ProjectSavedDir() / TEXT("SaveGames");
   512→
   513→	IFileManager& FileManager = IFileManager::Get();
   514→	TArray<FString> FoundFiles;
   515→	FileManager.FindFiles(FoundFiles, *SaveDirectory, TEXT("*.sav"));
   516→
   517→	for (const FString& FileName : FoundFiles)
   518→	{
   519→		// .sav 확장자 제거하여 슬롯 이름 추출
   520→		FString SlotName = FPaths::GetBaseFilename(FileName);
   521→
   522→		// SaveGame을 로드하여 컨텍스트 확인
   523→		UWjWorldLayoutSaveGame* SaveGame = Cast<UWjWorldLayoutSaveGame>(
   524→			UGameplayStatics::LoadGameFromSlot(SlotName, 0)
   525→		);
   526→
   527→		if (SaveGame && SaveGame->SavedContext == CurrentContext)
   528→		{
   529→			SlotNames.Add(SlotName);
   530→		}
   531→	}
   532→
   533→	UE_LOG(LogWjWorldPlacement, Log, TEXT("PlacementComponent: Found %d saved layout slots for context '%s'"),
   534→		SlotNames.Num(), *GetPlacementContextName(CurrentContext));
   535→	return SlotNames;
   536→}
