   538→bool UWjWorldPlacementComponent::DeleteLayoutSlot(const FString& SlotName)
   539→{
   540→	// SaveGame 삭제
   541→	if (!UGameplayStatics::DeleteGameInSlot(SlotName, 0))
   542→	{
   543→		UE_LOG(LogWjWorldPlacement, Warning, TEXT("PlacementComponent: Failed to delete save slot '%s'"), *SlotName);
   544→		return false;
   545→	}
   546→
   547→	// AW 컨텍스트: CSV 파일도 삭제
   548→	if (CurrentContext == EPlacementContext::ApproachingWall)
   549→	{
   550→		FString CSVPath = GetUserWallLayoutDirectory() / SlotName + TEXT(".csv");
   551→		IPlatformFile& PlatformFile = FPlatformFileManager::Get().GetPlatformFile();
   552→		if (PlatformFile.FileExists(*CSVPath))
   553→		{
   554→			PlatformFile.DeleteFile(*CSVPath);
   555→			UE_LOG(LogWjWorldPlacement, Log, TEXT("PlacementComponent: Deleted CSV '%s'"), *CSVPath);
   556→		}
   557→	}
   558→	// JumpMap 컨텍스트: CSV 파일도 삭제
   559→	else if (CurrentContext == EPlacementContext::JumpMap)
   560→	{
   561→		FString CSVPath = GetUserJumpMapLayoutDirectory() / SlotName + TEXT(".csv");
   562→		IPlatformFile& PlatformFile = FPlatformFileManager::Get().GetPlatformFile();
   563→		if (PlatformFile.FileExists(*CSVPath))
   564→		{
   565→			PlatformFile.DeleteFile(*CSVPath);
   566→			UE_LOG(LogWjWorldPlacement, Log, TEXT("PlacementComponent: Deleted CSV '%s'"), *CSVPath);
   567→		}
   568→	}
   569→
   570→	// 현재 로드된 슬롯이면 초기화
   571→	if (LoadedSlotName == SlotName)
   572→	{
   573→		LoadedSlotName.Empty();
   574→	}
   575→
   576→	UE_LOG(LogWjWorldPlacement, Log, TEXT("PlacementComponent: Deleted layout slot '%s'"), *SlotName);
   577→	return true;
   578→}
