   580→bool UWjWorldPlacementComponent::ExportLayoutAsCSV(const FString& FileName)
   581→{
   582→	// AW 컨텍스트에서만 동작
   583→	if (CurrentContext != EPlacementContext::ApproachingWall)
   584→	{
   585→		UE_LOG(LogWjWorldPlacement, Warning, TEXT("ExportLayoutAsCSV: Only available in ApproachingWall context"));
   586→		return false;
   587→	}
   588→
   589→	IWjWorldPlacementDataProvider* DataProvider = GetPlacementDataProvider();
   590→	if (!DataProvider)
   591→	{
   592→		UE_LOG(LogWjWorldPlacement, Error, TEXT("ExportLayoutAsCSV: No data provider"));
   593→		return false;
   594→	}
   595→
   596→	const TArray<FPlacedObjectSaveEntry>& PlacedObjects = DataProvider->GetPlacedObjects();
   597→	if (PlacedObjects.Num() == 0)
   598→	{
   599→		UE_LOG(LogWjWorldPlacement, Warning, TEXT("ExportLayoutAsCSV: No objects to export"));
   600→		return false;
   601→	}
   602→
   603→	// 그리드 설정 (기본값 사용, 추후 설정 가능하게 확장 가능)
   604→	const FApproachingWallGridConfig GridConfig;
   605→	const FVector& BrickSize = GridConfig.BrickSize;
   606→
   607→	// 1. 배치된 오브젝트의 바운딩 박스 계산
   608→	FVector MinBounds(FLT_MAX, FLT_MAX, FLT_MAX);
   609→	FVector MaxBounds(-FLT_MAX, -FLT_MAX, -FLT_MAX);
   610→
   611→	for (const FPlacedObjectSaveEntry& Entry : PlacedObjects)
   612→	{
   613→		const FVector& Location = Entry.Transform.GetLocation();
   614→		MinBounds.X = FMath::Min(MinBounds.X, Location.X);
   615→		MinBounds.Y = FMath::Min(MinBounds.Y, Location.Y);
   616→		MaxBounds.X = FMath::Max(MaxBounds.X, Location.X);
   617→		MaxBounds.Y = FMath::Max(MaxBounds.Y, Location.Y);
   618→	}
   619→
   620→	// 2. 그리드 크기 계산 (+1 = 위치 개수, +2 = 양쪽 1셀 패딩)
   621→	int32 GridColumns = FMath::CeilToInt((MaxBounds.X - MinBounds.X) / BrickSize.X) + 1 + 2;
   622→	int32 GridRows = FMath::CeilToInt((MaxBounds.Y - MinBounds.Y) / BrickSize.Y) + 1 + 2;
   623→
   624→	// 최소 크기 보장
   625→	GridColumns = FMath::Max(GridColumns, 3);
   626→	GridRows = FMath::Max(GridRows, 3);
   627→
   628→	// 그리드 원점: MinBounds에서 1칸 앞 (패딩용, 오브젝트가 인덱스 1부터 매핑)
   629→	FVector GridOrigin = MinBounds - FVector(BrickSize.X, BrickSize.Y, 0.0f);
   630→
   631→	// 3. 그리드 초기화 (-1 = Empty)
   632→	TArray<TArray<int32>> Grid;
   633→	Grid.SetNum(GridRows);
   634→	for (int32 Row = 0; Row < GridRows; ++Row)
   635→	{
   636→		Grid[Row].SetNum(GridColumns);
   637→		for (int32 Col = 0; Col < GridColumns; ++Col)
   638→		{
   639→			Grid[Row][Col] = -1;
   640→		}
   641→	}
   642→
   643→	// 4. 오브젝트를 그리드에 매핑 (RoundToInt로 CalculateBrickGridIndex와 일치)
   644→	for (const FPlacedObjectSaveEntry& Entry : PlacedObjects)
   645→	{
   646→		const FVector& Location = Entry.Transform.GetLocation();
   647→
   648→		// 월드 좌표 → 그리드 인덱스
   649→		int32 Col = FMath::RoundToInt((Location.X - GridOrigin.X) / BrickSize.X);
   650→		int32 Row = FMath::RoundToInt((Location.Y - GridOrigin.Y) / BrickSize.Y);
   651→
   652→		// 범위 체크
   653→		if (Row >= 0 && Row < GridRows && Col >= 0 && Col < GridColumns)
   654→		{
   655→			int32 BrickTypeValue = ObjectIdToBrickTypeValue(Entry.ObjectId);
   656→			Grid[Row][Col] = BrickTypeValue;
   657→		}
   658→	}
   659→
   660→	// 5. CSV 문자열 생성 (첫 줄에 메타데이터 포함)
   661→	FString CSVContent;
   662→
   663→	// ⭐ 메타데이터 헤더: CenterOffset 저장 (클라이언트 프리뷰 위치 동기화용)
   664→	// CalculateBrickPosition은 CenterOffset을 그리드 중심으로 사용하므로, 그리드 중심 좌표를 저장
   665→	FVector CenterOffset;
   666→	CenterOffset.X = GridOrigin.X + (GridColumns - 1) * 0.5f * BrickSize.X;
   667→	CenterOffset.Y = GridOrigin.Y + (GridRows - 1) * 0.5f * BrickSize.Y;
   668→	CenterOffset.Z = 0.0f;
   669→	CSVContent += FString::Printf(TEXT("#META:CenterOffset:%f,%f,%f\n"),
   670→		CenterOffset.X, CenterOffset.Y, CenterOffset.Z);
   671→
   672→	for (int32 Row = 0; Row < GridRows; ++Row)
   673→	{
   674→		for (int32 Col = 0; Col < GridColumns; ++Col)
   675→		{
   676→			CSVContent += FString::Printf(TEXT("%d"), Grid[Row][Col]);
   677→			if (Col < GridColumns - 1)
   678→			{
   679→				CSVContent += TEXT(",");
   680→			}
   681→		}
   682→		CSVContent += TEXT("\n");
   683→	}
   684→
   685→	// 6. 파일 저장
   686→	FString UserLayoutDir = GetUserWallLayoutDirectory();
   687→
   688→	// 디렉토리 생성
   689→	IPlatformFile& PlatformFile = FPlatformFileManager::Get().GetPlatformFile();
   690→	if (!PlatformFile.DirectoryExists(*UserLayoutDir))
   691→	{
   692→		PlatformFile.CreateDirectoryTree(*UserLayoutDir);
   693→	}
   694→
   695→	FString FilePath = UserLayoutDir / FileName + TEXT(".csv");
   696→
   697→	if (FFileHelper::SaveStringToFile(CSVContent, *FilePath))
   698→	{
   699→		LastExportedCSVPath = FilePath;
   700→		UE_LOG(LogWjWorldPlacement, Log, TEXT("ExportLayoutAsCSV: Exported to '%s' (Grid: %dx%d)"),
   701→			*FilePath, GridColumns, GridRows);
   702→		return true;
   703→	}
   704→	else
   705→	{
   706→		UE_LOG(LogWjWorldPlacement, Error, TEXT("ExportLayoutAsCSV: Failed to save file '%s'"), *FilePath);
   707→		return false;
   708→	}
   709→}
