   711→bool UWjWorldPlacementComponent::ExportJumpMapLayoutAsCSV(const FString& FileName)
   712→{
   713→	if (CurrentContext != EPlacementContext::JumpMap)
   714→	{
   715→		UE_LOG(LogWjWorldPlacement, Warning, TEXT("ExportJumpMapLayoutAsCSV: Only available in JumpMap context"));
   716→		return false;
   717→	}
   718→
   719→	IWjWorldPlacementDataProvider* DataProvider = GetPlacementDataProvider();
   720→	if (!DataProvider)
   721→	{
   722→		UE_LOG(LogWjWorldPlacement, Error, TEXT("ExportJumpMapLayoutAsCSV: No data provider"));
   723→		return false;
   724→	}
   725→
   726→	const TArray<FPlacedObjectSaveEntry>& PlacedObjects = DataProvider->GetPlacedObjects();
   727→	if (PlacedObjects.Num() == 0)
   728→	{
   729→		UE_LOG(LogWjWorldPlacement, Warning, TEXT("ExportJumpMapLayoutAsCSV: No objects to export"));
   730→		return false;
   731→	}
   732→
   733→	// CSV 생성: 헤더 + 오브젝트 행 (11번째 Properties 컬럼 포함)
   734→	FString CSVContent;
   735→	CSVContent += FString::Printf(TEXT("#META:MapName:%s\n"), *FileName);
   736→	CSVContent += TEXT("ObjectId,PosX,PosY,PosZ,RotPitch,RotYaw,RotRoll,ScaleX,ScaleY,ScaleZ,Properties\n");
   737→
   738→	for (const FPlacedObjectSaveEntry& Entry : PlacedObjects)
   739→	{
   740→		const FVector& Loc = Entry.Transform.GetLocation();
   741→		const FRotator Rot = Entry.Transform.GetRotation().Rotator();
   742→		const FVector& Scale = Entry.Transform.GetScale3D();
   743→
   744→		// CustomProperties를 Key=Value|Key=Value 형식으로 직렬화
   745→		FString PropsStr;
   746→		for (const auto& Pair : Entry.CustomProperties)
   747→		{
   748→			if (!PropsStr.IsEmpty()) PropsStr += TEXT("|");
   749→			PropsStr += FString::Printf(TEXT("%s=%s"), *Pair.Key, *Pair.Value);
   750→		}
   751→
   752→		CSVContent += FString::Printf(TEXT("%s,%f,%f,%f,%f,%f,%f,%f,%f,%f,%s\n"),
   753→			*Entry.ObjectId.ToString(),
   754→			Loc.X, Loc.Y, Loc.Z,
   755→			Rot.Pitch, Rot.Yaw, Rot.Roll,
   756→			Scale.X, Scale.Y, Scale.Z,
   757→			*PropsStr);
   758→	}
   759→
   760→	// 파일 저장
   761→	FString UserLayoutDir = GetUserJumpMapLayoutDirectory();
   762→	IPlatformFile& PlatformFile = FPlatformFileManager::Get().GetPlatformFile();
   763→	if (!PlatformFile.DirectoryExists(*UserLayoutDir))
   764→	{
   765→		PlatformFile.CreateDirectoryTree(*UserLayoutDir);
   766→	}
   767→
   768→	FString FilePath = UserLayoutDir / FileName + TEXT(".csv");
   769→	if (FFileHelper::SaveStringToFile(CSVContent, *FilePath))
   770→	{
   771→		LastExportedCSVPath = FilePath;
   772→		UE_LOG(LogWjWorldPlacement, Log, TEXT("ExportJumpMapLayoutAsCSV: Exported to '%s' (%d objects)"),
   773→			*FilePath, PlacedObjects.Num());
   774→		return true;
   775→	}
   776→
   777→	UE_LOG(LogWjWorldPlacement, Error, TEXT("ExportJumpMapLayoutAsCSV: Failed to save '%s'"), *FilePath);
   778→	return false;
   779→}
