   781→void UWjWorldPlacementComponent::TickComponent(float DeltaTime, ELevelTick TickType, FActorComponentTickFunction* ThisTickFunction)
   782→{
   783→	Super::TickComponent(DeltaTime, TickType, ThisTickFunction);
   784→
   785→	if (CurrentMode == EPlacementMode::Placing && PreviewActor)
   786→	{
   787→		const FPlaceableObjectDefinition* Def = Catalog ? Catalog->FindByObjectId(SelectedObjectId) : nullptr;
   788→		float GroundOffset = Def ? Def->GroundOffset : 0.0f;
   789→		FVector PlaceLocation;
   790→		bool bTraceSuccess = false;
   791→
   792→		if (bAirPlacementMode)
   793→		{
   794→			// Air 모드: 수평 평면과 교차
   795→			FVector AirLocation;
   796→			if (TraceAirPlane(AirLocation))
   797→			{
   798→				PlaceLocation = AirLocation + FVector(0.0f, 0.0f, GroundOffset);
   799→				bTraceSuccess = true;
   800→			}
   801→		}
   802→		else
   803→		{
   804→			// Ground 모드: 기존 바닥 트레이스
   805→			FHitResult HitResult;
   806→			if (TraceGroundUnderMouse(HitResult))
   807→			{
   808→				PlaceLocation = HitResult.ImpactPoint + FVector(0.0f, 0.0f, GroundOffset);
   809→				bTraceSuccess = true;
   810→			}
   811→		}
   812→
   813→		if (bTraceSuccess)
   814→		{
   815→			// AW 컨텍스트: 그리드 스냅 적용
   816→			if (CurrentContext == EPlacementContext::ApproachingWall)
   817→			{
   818→				PlaceLocation = SnapToGrid(PlaceLocation);
   819→			}
   820→
   821→			FRotator PlaceRotation = PreviewActor->GetCurrentRotation();
   822→			PreviewActor->UpdatePreviewTransform(PlaceLocation, PlaceRotation);
   823→
   824→			// 유효성 검사
   825→			bCurrentPreviewValid = IsPlacementLocationValid(PlaceLocation);
   826→			PreviewActor->SetPreviewValid(bCurrentPreviewValid);
   827→		}
   828→		else
   829→		{
   830→			bCurrentPreviewValid = false;
   831→			PreviewActor->SetPreviewValid(false);
   832→		}
   833→
   834→		// 3D 회전 축 기즈모 표시
   835→		DrawRotationAxisGizmo();
   836→	}
   837→
   838→	// JumpMap 컨텍스트: 체크포인트 위에 CheckpointOrder 번호 3D 표시
   839→	if (CurrentContext == EPlacementContext::JumpMap && CurrentMode != EPlacementMode::None)
   840→	{
   841→		IWjWorldPlacementDataProvider* DP = GetPlacementDataProvider();
   842→		if (DP)
   843→		{
   844→			for (const FPlacedObjectSaveEntry& Obj : DP->GetPlacedObjects())
   845→			{
   846→				if (Obj.ObjectId.ToString().Contains(TEXT("Checkpoint")))
   847→				{
   848→					const FString* OrderStr = Obj.CustomProperties.Find(TEXT("CheckpointOrder"));
   849→					if (OrderStr)
   850→					{
   851→						FVector TextLoc = Obj.Transform.GetLocation() + FVector(0, 0, 200.f);
   852→						DrawDebugString(GetWorld(), TextLoc,
   853→							FString::Printf(TEXT("CP #%s"), **OrderStr),
   854→							nullptr, FColor::Yellow, 0.f, true, 1.5f);
   855→					}
   856→				}
   857→			}
   858→		}
   859→	}
   860→
   861→	if (CurrentMode == EPlacementMode::Deleting)
   862→	{
   863→		// 삭제 모드: 호버 대상 갱신
   864→		AWjWorldPlacedObjectActor* NewHovered = TraceForPlacedObject();
   865→
   866→		if (NewHovered != HoveredObject)
   867→		{
   868→			if (HoveredObject)
   869→			{
   870→				HoveredObject->SetHighlighted(false);
   871→			}
   872→			HoveredObject = NewHovered;
   873→			if (HoveredObject)
   874→			{
   875→				HoveredObject->SetHighlighted(true);
   876→			}
   877→		}
   878→	}
   879→}
