   908→bool UWjWorldPlacementComponent::TraceAirPlane(FVector& OutLocation) const
   909→{
   910→	APlayerController* PC = GetPlayerController();
   911→	if (!PC)
   912→	{
   913→		return false;
   914→	}
   915→
   916→	FVector WorldLoc, WorldDir;
   917→	if (!PC->DeprojectMousePositionToWorld(WorldLoc, WorldDir))
   918→	{
   919→		return false;
   920→	}
   921→
   922→	// Ray-plane intersection: Plane at Z = AirPlaneHeight, Normal = UpVector
   923→	float Denom = FVector::DotProduct(WorldDir, FVector::UpVector);
   924→	if (FMath::Abs(Denom) < KINDA_SMALL_NUMBER)
   925→	{
   926→		return false; // 레이가 평면과 평행
   927→	}
   928→
   929→	float T = (AirPlaneHeight - WorldLoc.Z) / Denom;
   930→	if (T < 0.f || T > MaxAirTraceDistance)
   931→	{
   932→		return false; // 뒤쪽이거나 너무 먼 교차점
   933→	}
   934→
   935→	OutLocation = WorldLoc + WorldDir * T;
   936→	return true;
   937→}
