   939→bool UWjWorldPlacementComponent::IsPlacementLocationValid(const FVector& Location) const
   940→{
   941→	UWorld* World = GetWorld();
   942→	if (!World)
   943→	{
   944→		return false;
   945→	}
   946→
   947→	// AW 컨텍스트: 그리드 스냅 사용 시 더 작은 반경으로 정확히 같은 위치만 체크
   948→	// 일반 컨텍스트: 기존 겹침 반경 사용
   949→	float CheckRadius = (CurrentContext == EPlacementContext::ApproachingWall)
   950→		? GridOverlapCheckRadius
   951→		: OverlapCheckRadius;
   952→
   953→	// 겹침 체크: 기존 배치된 오브젝트와 겹치는지
   954→	TArray<FOverlapResult> Overlaps;
   955→	FCollisionQueryParams QueryParams;
   956→	QueryParams.AddIgnoredActor(GetOwner());
   957→	if (PreviewActor)
   958→	{
   959→		QueryParams.AddIgnoredActor(PreviewActor);
   960→	}
   961→
   962→	FCollisionShape SphereShape = FCollisionShape::MakeSphere(CheckRadius);
   963→	World->OverlapMultiByChannel(Overlaps, Location, FQuat::Identity, ECC_Visibility, SphereShape, QueryParams);
   964→
   965→	for (const FOverlapResult& Overlap : Overlaps)
   966→	{
   967→		if (Cast<AWjWorldPlacedObjectActor>(Overlap.GetActor()))
   968→		{
   969→			return false;
   970→		}
   971→	}
   972→
   973→	return true;
   974→}
   975→
   976→FVector UWjWorldPlacementComponent::SnapToGrid(const FVector& Location) const
   977→{
   978→	// AW 그리드 설정 사용
   979→	const FApproachingWallGridConfig GridConfig;
   980→	const FVector& BrickSize = GridConfig.BrickSize;
   981→
   982→	// 그리드 스냅: 각 축을 BrickSize 단위로 반올림
   983→	FVector SnappedLocation;
   984→	SnappedLocation.X = FMath::RoundToFloat(Location.X / BrickSize.X) * BrickSize.X;
   985→	SnappedLocation.Y = FMath::RoundToFloat(Location.Y / BrickSize.Y) * BrickSize.Y;
   986→	SnappedLocation.Z = Location.Z; // Z축은 스냅하지 않음 (바닥 높이 유지)
   987→
   988→	return SnappedLocation;
   989→}
