  1036→void UWjWorldPlacementComponent::DrawRotationAxisGizmo() const
  1037→{
  1038→	UWorld* World = GetWorld();
  1039→	if (!World || !PreviewActor)
  1040→	{
  1041→		return;
  1042→	}
  1043→
  1044→	FVector Origin = PreviewActor->GetActorLocation();
  1045→	FVector AxisDir;
  1046→	FColor AxisColor;
  1047→	FString AxisName;
  1048→
  1049→	switch (PreviewActor->GetCurrentRotationAxis())
  1050→	{
  1051→	case EPlacementRotationAxis::Yaw:
  1052→		AxisDir = FVector::UpVector;
  1053→		AxisColor = FColor::Blue;
  1054→		AxisName = TEXT("Yaw (Z)");
  1055→		break;
  1056→	case EPlacementRotationAxis::Pitch:
  1057→		AxisDir = FVector::RightVector;
  1058→		AxisColor = FColor::Green;
  1059→		AxisName = TEXT("Pitch (Y)");
  1060→		break;
  1061→	case EPlacementRotationAxis::Roll:
  1062→		AxisDir = FVector::ForwardVector;
  1063→		AxisColor = FColor::Red;
  1064→		AxisName = TEXT("Roll (X)");
  1065→		break;
  1066→	}
  1067→
  1068→	FVector ArrowEnd = Origin + AxisDir * GizmoArrowLength;
  1069→	DrawDebugDirectionalArrow(World, Origin, ArrowEnd, GizmoArrowSize, AxisColor, false, -1.f, 0, GizmoArrowThickness);
  1070→
  1071→	// 반대 방향 짧은 선분 (양방향 축 표현)
  1072→	FVector OppositeEnd = Origin - AxisDir * (GizmoArrowLength * 0.3f);
  1073→	DrawDebugLine(World, Origin, OppositeEnd, AxisColor, false, -1.f, 0, GizmoArrowThickness * 0.5f);
  1074→
  1075→	// 축 이름 + 스냅 각도 텍스트 표시
  1076→	FString InfoText = FString::Printf(TEXT("%s | %.0f°"), *AxisName, GetEffectiveSnapDegrees());
  1077→	DrawDebugString(World, ArrowEnd + FVector(0.f, 0.f, 15.f), InfoText, nullptr, AxisColor, 0.f, true, 1.f);
  1078→}
