  1211→			EIC->BindAction(DeleteAction, ETriggerEvent::Started, this, &UWjWorldPlacementComponent::OnDeleteAction);
  1212→		}
  1213→		if (ScrollAction)
  1214→		{
  1215→			EIC->BindAction(ScrollAction, ETriggerEvent::Triggered, this, &UWjWorldPlacementComponent::OnScrollAction);
  1216→		}
  1217→		if (ToggleAirModeAction)
  1218→		{
  1219→			EIC->BindAction(ToggleAirModeAction, ETriggerEvent::Started, this, &UWjWorldPlacementComponent::OnToggleAirModeAction);
  1220→		}
  1221→		if (CycleAxisAction)
  1222→		{
  1223→			EIC->BindAction(CycleAxisAction, ETriggerEvent::Started, this, &UWjWorldPlacementComponent::OnCycleAxisAction);
  1224→		}
  1225→		if (CycleSnapAction)
  1226→		{
  1227→			EIC->BindAction(CycleSnapAction, ETriggerEvent::Started, this, &UWjWorldPlacementComponent::OnCycleSnapAction);
  1228→		}
