  1369→int32 UWjWorldPlacementComponent::FindPlacedObjectIndex(AWjWorldPlacedObjectActor* Actor) const
  1370→{
  1371→	if (!Actor)
  1372→	{
  1373→		return INDEX_NONE;
  1374→	}
  1375→
  1376→	IWjWorldPlacementDataProvider* DataProvider = GetPlacementDataProvider();
  1377→	if (!DataProvider)
  1378→	{
  1379→		return INDEX_NONE;
  1380→	}
  1381→
  1382→	const TArray<FPlacedObjectSaveEntry>& PlacedObjects = DataProvider->GetPlacedObjects();
  1383→	FName TargetId = Actor->GetObjectId();
  1384→	FVector TargetLocation = Actor->GetActorLocation();
  1385→
  1386→	// ObjectId와 위치로 매칭 (동일 ObjectId가 여러 개 있을 수 있으므로 위치도 체크)
  1387→	for (int32 i = 0; i < PlacedObjects.Num(); ++i)
  1388→	{
  1389→		const FPlacedObjectSaveEntry& Entry = PlacedObjects[i];
  1390→		if (Entry.ObjectId == TargetId)
