   156→	{
   157→		return;
   158→	}
   159→
   160→	UE_LOG(LogWjWorldPlacement, Log, TEXT("GameStateLobby::RespawnAllPlacedObjects - Starting (Current SpawnedActors: %d, PlacedObjects: %d)"),
   161→		SpawnedActors.Num(), PlacedObjects.Num());
   162→
   163→	// 기존 스폰된 오브젝트 제거
   164→	for (AWjWorldPlacedObjectActor* Actor : SpawnedActors)
   165→	{
   166→		if (Actor && !Actor->IsPendingKillPending())
   167→		{
   168→			Actor->Destroy();
   169→		}
   170→	}
   171→	SpawnedActors.Empty();
   172→
   173→	// 카탈로그 폴백 로드 시도
   174→	EnsureCatalogLoaded();
   175→
   176→	// 카탈로그 없으면 스폰 불가
   177→	if (!Catalog)
   178→	{
   179→		UE_LOG(LogWjWorldPlacement, Warning, TEXT("GameStateLobby: Cannot respawn objects - no catalog set"));
   180→		return;
   181→	}
   182→
   183→	// 새로 스폰
   184→	for (const FPlacedObjectSaveEntry& Entry : PlacedObjects)
   185→	{
   186→		const FPlaceableObjectDefinition* Def = Catalog->FindByObjectId(Entry.ObjectId);
   187→		if (!Def)
   188→		{
   189→			UE_LOG(LogWjWorldPlacement, Warning, TEXT("GameStateLobby: ObjectId %s not found in catalog"),
   190→				*Entry.ObjectId.ToString());
   191→			continue;
   192→		}
   193→
   194→		UE_LOG(LogWjWorldPlacement, Log, TEXT("GameStateLobby: Spawning ObjectId=%s, MeshValid=%d, MeshPath=%s"),
   195→			*Entry.ObjectId.ToString(),
   196→			!Def->Mesh.IsNull(),
   197→			*Def->Mesh.ToString());
   198→
   199→		FActorSpawnParameters SpawnParams;
   200→		SpawnParams.SpawnCollisionHandlingOverride = ESpawnActorCollisionHandlingMethod::AlwaysSpawn;
   201→
   202→		UClass* SpawnClass = Def->ActorClassOverride
   203→			? Def->ActorClassOverride.Get()
   204→			: AWjWorldPlacedObjectActor::StaticClass();
   205→
   206→		AWjWorldPlacedObjectActor* NewActor = World->SpawnActor<AWjWorldPlacedObjectActor>(
   207→			SpawnClass,
   208→			Entry.Transform.GetLocation(),
   209→			Entry.Transform.GetRotation().Rotator(),
   210→			SpawnParams
   211→		);
   212→
   213→		if (NewActor)
   214→		{
   215→			NewActor->InitializeFromSaveData(Entry.ObjectId, Entry.Transform, *Def);
   216→			SpawnedActors.Add(NewActor);
   217→		}
   218→		else
   219→		{
   220→			UE_LOG(LogWjWorldPlacement, Error, TEXT("GameStateLobby: Failed to spawn actor for ObjectId=%s"), *Entry.ObjectId.ToString());
   221→		}
   222→	}
   223→
   224→	UE_LOG(LogWjWorldPlacement, Log, TEXT("GameStateLobby: Respawned %d objects"), SpawnedActors.Num());
   225→}
   226→
   227→void AWjWorldGameStateLobby::EnsureCatalogLoaded()
   228→{
   229→	// 이미 Catalog가 설정되어 있으면 스킵
   230→	if (Catalog)
   231→	{
   232→		return;
   233→	}
   234→
   235→	// DeveloperSettings에서 Catalog 로드 (폴백 메커니즘)
   236→	const UWjWorldDeveloperSettings* Settings = GetDefault<UWjWorldDeveloperSettings>();
   237→	if (!Settings || Settings->LobbyPlaceableCatalog.IsNull())
   238→	{
   239→		UE_LOG(LogWjWorldPlacement, Warning, TEXT("GameStateLobby: No LobbyPlaceableCatalog configured in DeveloperSettings"));
   240→		return;
   241→	}
   242→
   243→	Catalog = Settings->LobbyPlaceableCatalog.LoadSynchronous();
   244→	if (Catalog)
   245→	{
   246→		UE_LOG(LogWjWorldPlacement, Log, TEXT("GameStateLobby: Catalog loaded from DeveloperSettings (fallback)"));
   247→	}
   248→	else
   249→	{
   250→		UE_LOG(LogWjWorldPlacement, Error, TEXT("GameStateLobby: Failed to load LobbyPlaceableCatalog"));
   251→	}
   252→}
